(window.GIM_TS=window.GIM_TS||{})["Bava Batra.8"]={"from":192,"a":[["\u0003מבושם\u0004 (מתוקן ומשובח) \u0003אני מוכר לך\"\u0004 — \u0003חייב להעמיד לו\u0004 יין שיתקיים \u0003עד העצרת\u0004 (חג השבועות), \u0003ו\u0004אם אמר \"יין \u0003ישן\u0004 אני מוכר לך\" — חייב המוכר לתת לקונה יין שנעשה \u0003משל\u0004 הבציר של \u0003אשתקד\u0004 (השנה שעברה), \u0003ו\u0004אם אמר לו \"יין \u0003מיושן\u0004 אני מוכר לך\" — חייב המוכר לתת לקונה יין \u0003משל שלש שנים.\u0004","על הדין האמור בתחילת המשנה, שהמוכר יין לחבירו והחמיץ אינו חייב באחריותו, \u0003אמר ר' יוסי בר' חנינא: לא שנו אלא\u0004 כאשר היין נמצא חמוץ \u0003בקנקנים\u0004 של ה\u0003לוקח, אבל\u0004 אם נשאר היין \u0003בקנקנים\u0004 של ה\u0003מוכר\u0004 — \u0003אמר ליה\u0004 \u0005[\u0006יכול \u0005לומר לו]\u0006 הקונה: \u0003הא חמרך והא קנקנך\u0004 \u0005[הרי יינך והרי קנקניך],\u0006 קח אותם בחזרה והשב לי את כספי.","ושואלים: \u0003וכי\u0004 \u0005[כאשר]\u0006 ה\u0003קנקנין\u0004 של \u0003מוכר מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 המוכר: \u0003לא איבעי לך לשהויי\u0004 \u0005[היית צריך להשהות אותו]\u0006 זמן מרובה כל כך מזמן שקנית אותו עד שיחמיץ! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 הקונה שהוא צריך את היין \u0003למקפה\u0004 כתוספת לתבשיליו, שמשתמש בו מעט מעט, במשך זמן רב.","ושואלים: \u0003ומאי דוחקיה\u0004 \u0005[ומה דוחקו]\u0006 של \u0003ר' יוסי בר' חנינא לאוקמא למתניתין\u0004 \u0005[להעמיד,\u0006 להסביר, \u0005את משנתנו]\u0006 \u0003בקנקנין\u0004 של \u0003לוקח\u0004 ובמקרה מיוחד ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 הקונה שהיין מיועד \u0003למקפה? לוקמא\u0004 \u0005[שיעמיד\u0006 אותה\u0005]\u0006 \u0003בקנקנין\u0004 של \u0003מוכר ו\u0004במקרה ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 שהוא צריך את היין \u0003למקפה\u0004 ולכן הוא פטור מלשלם!","\u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[משנתנו היתה קשה לו],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 בהמשך: \u0003אם ידוע שיינו מחמיץ\u0004 — \u0003הרי זה מקח טעות\u0004 ויכול הקונה להחזיר את היין ולקבל בחזרה את כספו. ויש לשאול על כך: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 המוכר: \u0003לא איבעי לך לשהויי\u0004 \u0005[היית צריך להשהות אותו]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שמשנתנו עוסקת במקרה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 הקונה שהוא צריך אותו \u0003למקפה,\u0004 ולכן מתחילה מכר לו דבר שאינו ראוי לו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה\u0006 דעה זו\u0005]\u0006 של ר' יוסי בר' חנינא, הסבור שאם החמיץ היין בקנקניו של מוכר — אחריות המוכר היא, ולא של הלוקח שהיין ברשותו, על מה שאמר \u0003רב חייא בר יוסף,\u0004 ש\u0003אמר רב חייא בר יוסף: חמרא\u0004 \u0005[\u0006ב\u0005יין]\u0006 — \u0003מזלא דמריה גרים\u0004 \u0005[המזל של אדוניו גורם]\u0006 אם יחמיץ או לא, \u0003שנאמר: \"ואף כי היין בגד גבר יהיר\u0004 ולא ינוה","\u0003\"\u0004(חבקוק ב, ה), הרי שיין מחמיץ (\"בוגד\") לפי בעליו, שאם יהיר הוא — אף יינו יחמיץ. ואגב ענין זה מביאים דרשה נוספת על הפסוק, \u0003אמר רב מרי: האי מאן דיהיר\u0004 \u0005[מי שהוא גאוותן]\u0006 — \u0003אפילו אאינשי ביתיה לא מיקבל\u0004 \u0005[על אנשי ביתו,\u0006 על אשתו, \u0005אינו מקובל],\u0006 \u0003שנאמר: \"גבר יהיר ולא ינוה\"\u0004 (חבקוק ב, ה), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ולא ינוה\"?\u0004 כוונתו: אף \u0003בנוה\u0004 (בבית) \u0003שלו\u0004 אינו חי כאדם בביתו.","ועוד על נזק הגאוה הנלמד מאותו פסוק, \u0003אמר רב יהודה אמר רב:\u0004 \u0003כל המתגאה בטלית של תלמיד חכם,\u0004 כלומר, שמתלבש כדרך תלמידי חכמים \u0003ואינו תלמיד חכם\u0004 — \u0003אין מכניסין אותו במחיצתו של הקדוש ברוך הוא,\u0004 ורמז לדבר: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בעניינו של המתגאה \u0003\"ולא ינוה\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"אל נוה קדשך\"\u0004 (שמות טו, יג).","\u0003אמר רבא: האי מאן דזבין ליה חביתא דחמרא לחנואה\u0004 \u0003אדעתא לסבוייה\u0004 \u0005[מי שמוכר לו חבית יין לחנווני על דעת להשקות ממנו],\u0006 שהחנווני ימכור מאותה חבית מעט מעט לבאים לשתות יין, \u0003ותקיף אפלגא\u0004 \u0005[והחמיץ\u0006 היין \u0005בחצי]\u0006 \u0003או אתילתא\u0004 \u0005[בשליש\u0006 החבית\u0005],\u0006 \u0003דינא\u0004 \u0005[הדין]\u0006 \u0003הוא\u0004 ש\u0003מקבל לה מיניה\u0004 \u0005[אותה ממנו]\u0006 המוכר בחזרה, ויחזיר לקונה את כספו. ומוסיפים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 בזמן ש\u0003לא שני בברזא\u0004 \u0005[שינה\u0006 החנווני \u0005בברז]\u0006 שממנו מוציא את היין מהחבית, \u0003אבל\u0004 אם \u0003שני בברזא\u0004 \u0005[שינה בברז]\u0006 — \u0003לא,\u0004 שמא שינוי הברז הוא שגרם להחמצה. ועוד הסתייגות: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 ש\u0003לא מטא יומא דשוקא\u0004 \u0005[הגיע יום השוק]\u0006 שבו יכולים למכור הכל, \u0003אבל\u0004 אם \u0003מטא יומא דשוקא\u0004 \u0005[הגיע יום השוק]\u0006 ולא מכר החנווני אז את החבית, ולאחר מכן החמיץ היין — \u0003לא,\u0004 אינו יכול להחזיר לו את היין, שהתרשל החנווני בעבודתו, והשהה את היין יותר מדי.","\u0003ו\u0004עוד \u0003אמר רבא\u0004 בענין דומה: \u0003האי מאן דקביל חמרא אדעתא דממטי ליה לפרוותא\u0004 \u0005[מי שקיבל יין\u0006 בעיסקת שותפות \u0005על דעת להביא אותו לנמל]\u0006 של המקום הקרוי \u0003וול שפט\u0004 ולמכור אותו שם, \u0003ואדמטי התם זל\u0004 \u0005[ועד שהגיע לשם הוזל],\u0006 \u0003דינא\u0004 \u0005[הדין]\u0006 \u0003הוא\u0004 ש\u0003מקבל\u0004 הבעלים \u0003ליה\u0004 \u0005[אותו],\u0006","את ההפסד הזה, ואין זה על אחריות המוביל. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם עד שהגיע לוול שפט, \u0003הוה חלא\u0004 \u0005[נעשה\u0006 היין \u0005חומץ],\u0006 \u0003מאי\u0004 \u0005[מהו\u0006 הדין\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הלל לרב אשי, כי הואן בי\u0004 \u0005[כאשר היינו בבית]\u0006 \u0003רב כהנא אמר לן\u0004 \u0005[לנו]\u0006 הלכה כענין זה: \u0003חלא\u0004 \u0005[חומץ]\u0006 \u0003לא,\u0004 אינו צריך הבעלים לקבל, \u0003ו\u0004ש\u0003לא כ\u0004דעת \u0003ר' יוסי בר' חנינא,\u0004 הסבור כי כל זמן שהיין בקנקני המוכר — יכול להחזיר לו הקונה את היין. אלא אנו אומרים: שמא גם מזלו של המוביל גרם.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אפילו חלא נמי\u0004 \u0005[חומץ גם כן]\u0006 \u0003מקבל, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 — \u0003כ\u0004שיטת \u0003ר' יוסי בר' חנינא.\u0004","שנינו במשנה שהמוכר יין \u0003ישן\u0004 — חייב להעמיד לקונה יין \u0003משל אשתקד,\u0004 ואם אמר לו: יין מיושן — חייב להעמיד לו יין משל שלוש שנים."],["\u0003תאנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בהסבר הדברים: \u0003ומיישן והולך עד החג\u0004 (חג הסוכות), שצריך שיהא היין נשמר שלוש שנים שלימות ושיתקיים עד חג הסוכות.","\u0003המוכר מקום\u0004 (שטח אדמה) \u0003לחבירו, וכן\u0004 פועל \u0003המקבל מקום מחבירו\u0004 כדי \u0003לעשות לו בית חתנות לבנו,\u0004 שהבן הנשוי זה עתה יגור בבית הקטן הזה לפי שעה, או \u0003בית אלמנות לבתו\u0004 שנתאלמנה וחוזרת לגור בביתו — \u0003בונה\u0004 על שטח אדמה של \u0003ארבע אמות על שש\u0004 אמות, אלו \u0003דברי ר' עקיבא; ר' ישמעאל אומר:\u0004 בנין קטן כזה \u0003רפת בקר היא זו\u0004 ולא דירת בני אדם.","\u0003הרוצה לעשות רפת בקר\u0004 — \u0003בונה ארבע אמות על שש.\u0004","\u0003בית קטן\u0004 הוא \u0003שש על שמונה,\u0004 בית \u0003גדול\u0004 — \u0003שמונה על עשר, טרקלין\u0004 — הוא \u0003עשר על עשר.\u0004 וכל אחד מאלו \u0003רומו\u0004 (גובהו) \u0003כחצי ארכו וכחצי רחבו\u0004 יחד. ו\u0003ראיה לדבר,\u0004 \u0003רבן שמעון בן גמליאל אומר: כבנין ההיכל,\u0004 שכך היו המידות שלו — ארבעים אמה ארכו, ועשרים אמה רוחבו. וגובהו, שהוא שלושים אמה, הריהו מחצית מן הצירוף של שניהם.","ושואלים על לשון המשנה: \u0003למה לי למיתנא\u0004 \u0005[לשנות]\u0006 \u0003בית חתנות לבנו ובית אלמנות לבתו? ליתני\u0004 \u0005[שישנה]\u0006 \u0003בית חתנות לבנו ולבתו, ובית אלמנות לבנו ולבתו!\u0004 ומשיבים: \u0003מלתא אגב אורחיה קא משמע לן\u0004 \u0005[דבר בדרך אגב השמיע לנו],\u0006 \u0003דלא דרכא דחתנא למידר בי חמוה\u0004 \u0005[שאין דרך חתן לגור בבית חמיו],\u0006 אין זו דרך ארץ,","\u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 \u0003בספר בן סירא: הכל שקלתי בכף מאזנים ולא מצאתי\u0004 דבר שהוא \u0003קל מסובין. ו\u0004אולם \u0003קל מסובין\u0004 מבחינה מוסרית — \u0003חתן הדר בבית חמיו, וקל מחתן\u0004 הדר בבית חמיו — \u0003אורח מכניס אורח. וקל מאורח\u0004 — \u0003משיב דבר בטרם ישמע\u0004 את השאלה כראוי, \u0003שנאמר: \"משיב דבר בטרם ישמע אולת היא לו וכלמה\"\u0004 (משלי יח, יג). ולכן לא נשנה במשנה ענין זה של העושה בית חתנות לבתו.","שנינו במשנה ש\u0003ר' ישמעאל אומר: רפת בקר היא זו.\u0004 ומיד אחר כך שנינו: \u0003הרוצה לעשות\u0004 רפת בקר בונה ארבע אמות על שש. ושואלים: הלכה זו של \u0003רפת בקר מאן קתני לה\u0004 \u0005[מי שנה אותה]?\u0006 \u0003איכא דאמר\u0004 \u0005[יש\u0006 מי \u0005שאומר]\u0006 ש\u0003ר' ישמעאל קתני לה\u0004 \u0005[שנה אותה]\u0006 וכהמשך לדבריו. \u0003ואיכא דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]\u0006 ש\u0003ר' עקיבא קתני לה\u0004 \u0005[שנה אותה]\u0006 וכתשובה לדברי ר' ישמעאל.","ומסבירים: \u0003איכא דאמר\u0004 \u0005[יש\u0006 מי \u0005שאומר]\u0006 ש\u0003ר' עקיבא קתני לה\u0004 \u0005[שנה],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר],\u0006 כך הוא משיב לר' ישמעאל: \u0003אף על פי ש\u0004אכן \u0003רפת בקר היא,\u0004 מכל מקום \u0003פעמים שאדם עושה דירתו\u0004 קטנה \u0003כרפת בקר,\u0004 ועל כך יכול המוכר או הקבלן להסתמך, ואינו חייב ביותר ממידות אלה של ארבע אמות על שש אמות. \u0003ואיכא דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]\u0006 ש\u0003ר' ישמעאל קתני לה\u0004 \u0005[שנה אותה]\u0006 כהמשך לדבריו, \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר]\u0006 לר' עקיבא: מידה זו שנתת לבית חתנות — רפת בקר היא זו, \u0003שהרוצה לעשות רפת בקר, עושה ארבע אמות על שש\u0004 כמידות אלה שהוזכרו בדברי ר' עקיבא, אבל בית למגורי אדם צריך להיות גדול יותר.","שנינו במשנה ש\u0003טרקלין\u0004 הוא \u0003עשר על עשר.\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003טרקלין?\u0004 — מה שנקרא בארמית \u0003קובתא בי וורדי\u0004 \u0005[אהל\u0006 הנמצא ב\u0005בית,\u0006 במקום, \u0005הוורדים].\u0006","\u0003תאני\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003וקנתיר\u0004 דורש שטח גדול יותר והוא \u0003שתים עשרה\u0004 אמות אורך \u0003על שתים עשרה\u0004 אמות רוחב. ומסבירים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"קנתיר\"?\u0004 — \u0003תרבץ אפדני\u0004 \u0005[חצר של ארמון,\u0006 העשויה לנוי\u0005].\u0006","שנינו: \u0003רומו כחצי ארכו וכחצי רחבו,\u0004 ו\u0003ראיה לדבר, רבן שמעון בן גמליאל אומר: כבנין היכל.\u0004 ושואלים: \u0003\"ראיה לדבר\" מאן קתני לה\u0004 \u0005[מי שנה אותה]?\u0006 \u0003איכא דאמר\u0004 \u0005[יש\u0006 מי \u0005שאומר]\u0006 ש\u0003רבן שמעון בן גמליאל קתני לה\u0004 \u0005[שנה אותה],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר]:\u0006 \u0003ראיה לדבר מנין? אמר רבן שמעון בן גמליאל: הכל כבנין היכל.\u0004","\u0003ואיכא דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]\u0006 שה\u0003תנא קמא קתני לה\u0004 \u0005[הראשון שנה אותה],\u0006 \u0003ורבן שמעון בן גמליאל אתמוהי קא מתמה\u0004 \u0005[תמה\u0006 על דבריו\u0005],\u0006 \u0003והכי קאמר ליה\u0004 \u0005[וכך אומר לו]\u0006 \u0003לתנא קמא\u0004 \u0005[הראשון]:\u0006 \u0003ראיה מנין\u0004 אתה מביא לסברה זו — \u0003מבנין היכל, אטו כולי עלמא\u0004 \u0005[וכי כל העולם]\u0006 \u0003כבנין היכל עבדי\u0004 \u0005[עושים]?\u0006","אלא הכל בונים כדרכם, וכמנהג המדינה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אחרים אומרים: רומו כקורותיו\u0004 התומכות את התקרה לרוחב הבית. ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 התנא קמא פשוט יותר: \u0003רומו כרחבו!\u0004 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003ביתא מעילאי רווחא\u0004 \u0005[בית נעשה קצת יותר מרווח מלמעלה]\u0006 שהכתלים צרים יותר בחלקם העליון, ולכן קצרות הקורות יותר מרוחב הבית למטה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003משום דאיכא בי כווי\u0004 \u0005[שיש מקום החלונות],\u0006 פתחים קטנים בעובי הכתלים שבהם מניחים את הקורות, ונמצא שהקורות ארוכות מרוחב הבית, ולפי ברייתא זו גובהו של הבית גדול מעט מרוחבו.","בענין זה של הראיה מן ההיכל, מסופר ש\u0003ר' חנינא נפק לקרייתא\u0004 \u0005[יצא לכפרים],\u0006 ושם \u0003רמו ליה קראי אהדדי\u0004 \u0005[השליכו,\u0006 הראו לו סתירה בין שני \u0005כתובים מזה על זה]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והבית אשר בנה המלך שלמה לה' ששים אמה ארכו ועשרים רחבו ושלשים אמה קומתו\"\u0004 (מלכים א ו, ב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בתיאור החלק הפנימי של ההיכל: \u0003\"ולפני הדביר עשרים אמה ארך ועשרים אמה רחב ועשרים אמה קומתו\"\u0004 (מלכים א ו, כ), הרי שעשרים אמה קומתו, ולא שלושים! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כי קא חשיב\u0004 \u0005[כאשר הוא מונה]\u0006 בפסוק השני — \u0003משפת\u0004 ה\u0003כרובים ולמעלה\u0004 הוא חושב, שלמעלה מן הכרובים שגובהם עשר אמות היו עוד עשרים אמה.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 הכתוב בכך\u0005]\u0006 שאינו מחשיב את מקומם של הכרובים?"],["\u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003למטה,\u0004 מקום הכרובים, הריהו \u0003כלמעלה\u0004 מגובה הכרובים, \u0003מה למעלה אין משמש כלום,\u0004 כלומר, השטח שמעל הכרובים אין בו שום דבר ואין החלל מכיל דבר, \u0003אף למטה אין משמש כלום,\u0004 שהמקום אינו נחוץ לדברים המצויים בו, לפי שאינם תופסים מקום בעולם החומרי.","\u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדיוק מכתוב זה \u0003לר' לוי,\u0004 ש\u0003אמר ר' לוי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן: דבר זה מסורת בידינו מאבותינו\u0004 — \u0003מקום ארון וכרובים אינו מן המדה\u0004 שאינו נמדד במידה חומרית ואינו תופס מקום בקודש הקודשים. ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ארון\u0004 הברית \u0003שעשה משה,\u0004 כאשר הכניסוהו לקודש הקודשים במקדש שלמה, שכל רוחבו היה עשרים אמה, \u0003יש לו\u0004 לארון \u0003ריוח עשר אמות לכל רוח ורוח\u0004 משני צדדיו, כי הוא עצמו אינו תופס מקום כלל.","וכן \u0003אמר רבנאי אמר שמואל: כרובים\u0004 שבמקדש שעשה שלמה, \u0003בנס הן עומדין, שנאמר: \"וחמש אמות כנף הכרוב האחת וחמש אמות כנף הכרוב השנית עשר אמות מקצות כנפיו ועד קצות כנפיו\"\u0004 (מלכים א ו, כד), וכיוצא בזה מידת כנפיו של הכרוב השני, ואם כן, \u0003גופייהו היכא הוו קיימי\u0004 \u0005[גופיהם\u0006 של הכרובים \u0005איך היו עומדים]?\u0006 שהרי שתי הכנפיים עצמן, שהן עשרים אמה, מילאו את כל רוחב הבית! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בנס הן עומדין\u0004 ואינם תופסים מקום.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי:\u0004 כיצד ניתן להוכיח מכאן שבנס היו עומדים? \u0003ודלמא\u0004 \u0005[ושמא]\u0006 לא היו כנפי הכרובים יוצאות מצידי גופם, אלא \u0003בולטין כתרנגולין הוו קיימי\u0004 \u0005[היו עומדים],\u0006 שגופם בולט מלפנים, וכנפיהם יוצאות ממרכז גבם, ונמצא שהגוף אינו תופס מקום נוסף! ובדומה לכך \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003זה שלא כנגד זה הוו קיימי\u0004 \u0005[היו עומדים]\u0006 הכרובים, אלא במקביל, ולכן יש להם מקום! ועוד \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בר יעקב: ודלמא באלכסונא הוו קיימי\u0004 \u0005[ושמא באלכסון היו עומדים]!\u0006","וכן \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 \u0003ודלמא ביתא מעילאי רווח\u0004 \u0005[ושמא\u0006 נאמר כי \u0005בית מרווח יותר למעלה],\u0006 ורוחב הבית במקום בו יוצאות הכנפיים מן הגוף היה יותר מעשרים אמה, ורק למעלה היה רוחב הבית עשרים אמה, שכן הדרך היא לבנות בית כשקירותיו הולכים וצרים כלפי מעלה! ועוד \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: ודלמא מיכף הוו כייפי ידייהו\u0004 \u0005[ושמא היו כופפים\u0006 קצת \u0005את ידיהם],\u0006 כלומר, את כנפיהם, שלא היו פרושות לגמרי! \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: ודלמא שלחופי הוו משלחפי\u0004 \u0005[ושמא היו משולבים זה בזה]\u0006 בקצות הכנפיים, ולכן לא היו צריכים כל כך הרבה מקום!","אגב דיון זה בכרובים, שואלים: \u0003כיצד הן,\u0004 הכרובים, \u0003עומדין? ר' יוחנן ור' אלעזר\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: פניהם איש אל אחיו, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פניהם לבית,\u0004 כלומר, כלפי פנים. ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003פניהם איש אל אחיו, הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ופניהם לבית\"\u0004 (דברי הימים ב ג, יג)! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן בזמן שישראל עושין רצונו של מקום\u0004 פונים הם זה לזה, כסימן לריצוי ואהבה, \u0003כאן בזמן שאין ישראל עושין רצונו של מקום\u0004 פניהם לא זה אל זה, אלא לבית.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003ופניהם לבית, הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ופניהם איש אל אחיו\"\u0004 (שמות כה, כ)! ומשיבים: \u0003דמצדדי אצדודי\u0004 \u0005[שהם פונים קצת הצידה]\u0006 להסתכל זה בזה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אונקלוס הגר אמר: כרובים \"מעשה צעצעים\"\u0004 (דברי הימים ב ג, י) \u0003הן, ומצודדים פניהם\u0004 אל ארון העדות \u0003כתלמיד הנפטר מרבו.\u0004","\u0003מי שיש לו בור\u0004 השייך לו \u0003לפנים מביתו של חבירו\u0004 וזכותו להשתמש בבור — \u0003נכנס\u0004 אל הבית \u0003בשעה שדרך בני אדם נכנסין, ויוצא בשעה שדרך בני אדם יוצאין,\u0004 אבל אין הוא נכנס ויוצא בשעות שבהן אנשים אינם נוהגים להיכנס ולצאת מביתם. \u0003ואינו מכניס בהמתו\u0004 אל תוך הבית \u0003ומשקה\u0004 אותה \u0003מבורו, אלא ממלא\u0004 מים בכלי \u0003ומשקה\u0004 את הבהמה \u0003מבחוץ. וזה,\u0004 בעל הבור, \u0003עושה לו פותחת\u0004 (מפתח) לדרך הגישה לבור, \u0003וזה\u0004 בעל הבית \u0003עושה לו פותחת.\u0004","על מה ששנינו במשנה שבעל הבור ובעל הבית שניהם עושים \u0003פותחת\u0004 לבור, שואלים: \u0003להיכא\u0004 \u0005[להיכן]?\u0006 \u0003אמר ר' יוחנן: שניהם לבור.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בעל הבור\u0004 עושה מפתח, משום ש\u0003בעי לאשתמורי מיא דבוריה\u0004 \u0005[רוצה\u0006 הוא \u0005לשמור\u0006 את ה\u0005מים של בורו],\u0006 \u0003אלא בעל הבית למה ליה\u0004 \u0005[לו]\u0006 לעשות מפתח לבור? והרי אינו רשאי להשתמש במי הבור, שאינו שלו! \u0003אמר ר' אלעזר:\u0004"],["\u0003משום חשד אשתו\u0004 בגלל בעל הבור. שכיון שבעל הבור יודע שאין הוא יכול לפתוח את הבור אלא על ידי המפתח האחר שנמצא ברשות בעל הבית — לא יכנס בשעות שבעל הבית אינו מצוי בביתו, וכך לא יבוא הבעל לחשוד בו שהוא מתייחד שם עם אשתו.","\u0003מי שיש לו גינה לפנים מגינתו של חברו\u0004 ויש לו זכות לעבור דרך גינת חבירו אל גינתו — \u0003נכנס\u0004 לגינתו \u0003בשעה שדרך בני אדם נכנסים, ויוצא בשעה שדרך בני אדם יוצאין,\u0004 ולא בשעות שאינן מקובלות, שלא יפריע לבעל הגינה. \u0003ו\u0004אף שמותר לו עצמו לעבור בגינת חבירו, \u0003אינו מכניס לתוכה תגרין\u0004 שיבואו לקנות מן הגינה שלו, הפנימית, משום שמרבים המולה והורסים הזריעה, \u0003ו\u0004כן \u0003לא יכנס מתוכה\u0004 על מנת להיכנס \u0003לתוך שדה אחרת\u0004 הסמוכה לה. \u0003והחיצון\u0004 בעל הגינה החיצונית, \u0003זורע את הדרך\u0004 לגינה הפנימית.","אבל אם \u0003נתנו לו\u0004 לבעל הגינה הפנימית \u0003דרך\u0004 בגינה החיצונית שאינה עוברת באמצע גינתו של החיצון, אלא \u0003מן הצד, מדעת\u0004 (בהסכמת) \u0003שניהן\u0004 — \u0003נכנס בשעה שהוא רוצה ויוצא בשעה שרוצה, ומכניס לתוכה תגרין, ו\u0004אולם \u0003לא יכנס מתוכה לתוך שדה אחרת. זה וזה,\u0004 גם בעל הגינה הפנימית וגם בעל הגינה החיצונית, \u0003אינן רשאים לזורעה\u0004 לאותה דרך העוברת מן הצד.","\u0003אמר רב יהודה אמר שמואל:\u0004 מי שאמר לחבירו \u0003\"אמה\u0004 (תעלת מים) לצורך \u0003בית השלחין\u0004 (שדה המושקה בידי אדם) \u0003אני מוכר לך\"\u0004 — \u0003נותן לו\u0004 שטח ברוחב \u0003שתי אמות ל\u0004צורך \u0003תוכה\u0004 (חללה) של התעלה הזו, \u0003ו\u0004עוד \u0003אמה מכאן ואמה מכאן ל\u0004שני \u0003אגפיה\u0004 ( צידיה) המוגבהים. אם אמר לו \u0003\"אמה בית הקילון\u0004 (שהיא תעלת מים קטנה יותר מאמה בית השלחין) \u0003אני מוכר לך\"\u0004 — \u0003נותן לו אמה אחת לתוכה\u0004 של התעלה, \u0003וחצי אמה מכאן וחצי אמה מכאן לאגפיה.\u0004","ושואלים: \u0003ואותן אגפיים מי זורעם,\u0004 למי הרשות בידו להשתמש בהם לצורך זריעה? \u0003רב יהודה אמר שמואל: בעל השדה זורעם; רב נחמן אמר שמואל: בעל השדה נוטעם,\u0004 שמותר לו לנטוע בהם אילנות. ומעירים בהסבר שיטותיהם: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003זורעם,\u0004 שמותר לבעל השדה לזרוע אותם, \u0003כל שכן נוטעם. ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003נוטעם\u0004 — דווקא לכך יש לו זכות, \u0003אבל זורעם\u0004 — \u0003לא,\u0004 כי \u0003חלחולי מחלחולי\u0004 \u0005[מחלחלים,\u0006 מתפשטים\u0005]\u0006 הזרעים באדמה, מרפים אותה, ומזיקים בכך לאמת המים.","\u0003ו\u0004עוד בענין זה \u0003אמר רב יהודה אמר שמואל: אמת המים שכלו\u0004 (התפוררו ונעלמו) \u0003אגפיה\u0004 — \u0003מתקנה מ\u0004האדמה שב\u0003אותה שדה\u0004 הסמוכה לה, למרות שהשדה אינה שלו, כי \u0003בידוע שלא כלו אגפיה\u0004 של אותה אמה \u0003אלא באותה שדה,\u0004 לשם התפזר העפר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא, ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 בעל השדה לבעל האמה: \u0003מייך אשפלוה לארעיך\u0004 \u0005[המים\u0006 שעברו באמה \u0005שלך\u0006 הם ש\u0005השפילו את אדמתך]\u0006 הם שסחפו את האדמה איתם, ולא נכנסה לשדה שלי! \u0003אלא אמר רב פפא:\u0004 טעם הדבר איננו זה, אלא \u0003שעל מנת כן קבל עליו בעל השדה\u0004 כאשר נתן לבעל האמה זכות לתעלה, שישתמש באדמה שלו לצורך תיקון אגפיה של האמה.","\u0003מי שהיתה דרך הרבים עוברת לתוך שדהו, נטלה\u0004 מהם, חסם את הדרך הזו לפני הרבים, \u0003ונתן להם\u0004 במקומה דרך אחרת \u0003מן הצד\u0004 בתוך שדהו — \u0003מה שנתן\u0004 לרבים \u0003נתן, ו\u0004גם \u0003שלו,\u0004 הדרך שנטל מהם — \u0003לא הגיעו,\u0004 והם רשאים להמשיך להשתמש בה.","ועוד בדיני מכירת קרקעות ודרכים: \u0003דרך היחיד,\u0004 כגון המוכר לחבירו דרך לעבור בתוך שדהו — רוחבה הוא \u0003ארבע אמות. דרך הרבים\u0004 — \u0003שש עשרה אמה. דרך המלך\u0004 — \u0003אין לה שיעור\u0004 רוחב קבוע, אלא לפי מה שיקבע המלך בכל מקרה ומקרה. \u0003דרך הקבר\u0004 שעושים לצורך הלוויה — גם היא \u0003אין לה שיעור. המעמד\u0004 המקום שבו היו עומדים לנחם את האבלים — \u0003דייני צפורי אמרו\u0004 כי שיעורו \u0003בית\u0004 (שטח זריעה של) \u0003ארבעה קבין\u0004 (שני שליש של בית סאה).","על ההלכה הראשונה במשנה, שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003שלו לא הגיעו,\u0004 ואין הוא זכאי לקבל לעצמו את הדרך? והרי נתן לרבים דרך חילופית! אם משום שאינו יכול להתדיין בבית הדין עם כל עובר — \u0003לינקוט פזרא וליתיב\u0004 \u0005[שיקח מקל וישב]\u0006 בדרך וימנע מאנשים לעבור! ומכיון שלא התירו לעשות כן \u0003שמעת מינה\u0004 \u0005[\u0006האם \u0005לומד אתה מכאן]:\u0006 \u0003לא עביד איניש דינא לנפשיה\u0004 \u0005[אין אדם עושה דין לעצמו]\u0006 \u0003אפילו במקום פסידא\u0004 \u0005[הפסד]?\u0006","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 אכן, מעיקר הדין רשאי היה לעשות זאת, ואולם \u0003גזירה\u0004 היא שגזרו חכמים שלא יחסום את דרכם הקודמת של הרבים, גם אם הוא נותן להם דרך חילופית, \u0003שמא יתן להן דרך עקלתון\u0004 שמעקמת ומאריכה את דרכם. \u0003רב משרשיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר:\u0004 מדובר במשנה \u0003בנותן להם דרך עקלתון\u0004 במקום הדרך הישירה שהיתה להם מקודם, שאין לו רשות לעשות כן, והרבים רשאים להמשיך ללכת בדרך הקודמת."],["\u0003רב אשי אמר: כל\u0004 מקרה שבעל השדה נותן לרבים דרך \u0003מן הצד\u0004 במקום הדרך העוברת בתוך שדהו — \u0003דרך עקלתון היא,\u0004 שאמנם היא \u0003קרובה לזה\u0004 הבא ממקום אחד, \u0003ו\u0004אולם היא \u0003רחוקה לזה\u0004 הבא מצד אחר.","עוד שואלים על חלקו הראשון של דין המשנה — שמה שנתן להם נתן: כיון שאינו רשאי ליטול מהם את הדרך הישנה, \u0003ולימא להו\u0004 \u0005[ושיאמר להם]:\u0006 \u0003שקלו דידכו והבו\u0004 \u0005[קחו\u0006 בחזרה \u0005את\u0006 הדרך הישנה \u0005שלכם ותנו]\u0006 \u0003לי דידי\u0004 \u0005[\u0006את \u0005שלי],\u0006 את הדרך שנתתי לכם! ומשיבים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי]?\u0006 כשיטת \u0003ר' אליעזר היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003ר' אליעזר: רבים שבררו דרך לעצמם\u0004 והחלו ללכת בתוך שדהו של אדם מסויים, \u0003מה שבררו בררו\u0004 ואי אפשר לקחת אותה מהם.","ושואלים: ו\u0003לר' אליעזר,\u0004 וכי \u0003רבים גזלנים נינהו\u0004 \u0005[הם]?\u0006 כיצד רשאים הם לקחת לעצמם דרך העוברת בשדהו של אחר? \u0003אמר רב גידל אמר רב:\u0004 מדובר \u0003כגון שאבדה להן דרך באותה שדה,\u0004 כלומר, שהיתה פעם דרך הרבים עוברת באותה שדה ואבדה הדרך על ידי חרישה שנחרשה השדה, והרבים בחרו לעצמם במקומה דרך אחרת, וכיון שבחרו בה — אין ליטלה מהם.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, שמדובר כשאבדה להם דרך בשדהו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אמר רבה בר רב הונא, אמר רב\u0004 ש\u0003אין הלכה כר' אליעזר?\u0004 והרי מסתבר טעמו! ומשיבים: \u0003מאן דמתני הא\u0004 \u0005[מי ששונה\u0006 את \u0005זו]\u0006 \u0003לא מתני הא\u0004 \u0005[שונה\u0006 את \u0005זו].\u0006 כלומר, מי שמסביר שהכוונה היא שאבדה להם דרך, הוא פוסק שהלכה כר' אליעזר. וזה שאינו פוסק הלכה כר' אליעזר לא פירש באופן זה, אלא הוא סבור שמדובר כשביררו להם מלכתחילה דרך בעצמם.","ושואלים: \u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 המשנה \u0005מהו]?\u0006 מדוע אין בעל השדה יכול להחזיר את המצב לקדמותו: שהרבים יקבלו את הדרך הישנה שלהם, והוא יטול לעצמו את הדרך החדשה שנתן להם? ומשיבים: \u0003משום\u0004 מה שאמר \u0003רב יהודה,\u0004 ש\u0003אמר רב יהודה: מצר שהחזיקו בו רבים\u0004 — \u0003אסור לקלקלו,\u0004 והרי נתן להם דרך והחזיקו בה.","ושואלים: \u0003ו\u0004לשיטת \u0003ר' אליעזר,\u0004 ש\u0003רבים\u0004 שבררו להם דרך קנו אותה, \u0003במאי קנו ליה\u0004 \u0005[במה קנו אותה]\u0006 את הדרך הזו? הרי לא עשו בה מעשה של חזקה! ומשיבים: \u0003בהילוכא\u0004 \u0005[בהילוך]\u0006 שהלכו בה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם קונה השדה \u0003הלך בה לארכה ולרחבה\u0004 — \u0003קנה\u0004 על ידי כך \u0003מקום הילוכו,\u0004 שאף ההילוך נחשב למעשה קנין, אלו \u0003דברי ר' אליעזר. וחכמים אומרים:\u0004 \u0003אין הילוך מועיל כלום\u0004 בקנין \u0003עד שיחזיק\u0004 באחת מדרכי הקנין.","\u0003אמר ר' אלעזר, מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לאברהם בהבטחת הארץ: \u0003\"קום התהלך בארץ לארכה ולרחבה כי לך אתננה\"\u0004 (בראשית יג, יז), ללמדנו שעשה קנין בארץ על ידי ההילוך בה. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים על כך? \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום חביבותא\u0004 \u0005[חיבתו]\u0006 של \u0003אברהם הוא דקאמר ליה הכי\u0004 \u0005[שאמר לו כך],\u0006 \u0003כדי שיהא\u0004 כל מקום שהלך בו \u0003נוח לכבוש לפני בניו,\u0004 אבל אין ההילוך כשלעצמו מעשה של קנין.","\u0003אמר ר' יוסי בר' חנינא: מודים חכמים לר' אליעזר בשביל של כרמים,\u0004 ש\u0003הואיל ו\u0004כל עיקרו \u0003נעשה ל\u0004צורך \u0003הילוך\u0004 — \u0003נקנה\u0004 הוא לקונה אותו \u0003בהילוך.\u0004","ובענין מכירת שביל של כרמים, מסופר: \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003רב יצחק בר אמי\u0004 לדין בענין שיעור רוחבו של שביל כזה, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הבו ליה כי היכי דדרי טונא דשבישתא והדר\u0004 \u0005[תנו לו\u0006 רוחב \u0005כמו שנושאים בו משא של זמורות וחוזרים,\u0006 מסתובבים\u0005],\u0006 כלומר, כאורכה של חבילת זמורות. ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דברים אלה \u0003אלא דמסיימין מחיצתא\u0004 \u0005[ש\u0006יש שם \u0005מחיצות מוגדרות],\u0006 שיש שם גדר ואז צריך לפרוץ את הגדרות כדי להרחיב את השביל, \u0003אבל\u0004 כאשר \u0003לא מסיימין מחיצתא\u0004 \u0005[מוגדרות המחיצות],\u0006 הרוחב שצריך לתת הוא \u0003כי היכי דשקיל כרעא ומנח כרעא\u0004 \u0005[כמו שמרים\u0006 אדם \u0005רגל ומניח רגל\u0006 אחרת\u0005],\u0006 ובכך דיו.","שנינו במשנה ש\u0003דרך היחיד\u0004 רוחבה הוא \u0003ארבע אמות. תנא\u0004 \u0005[שנה\u0006 החכם\u0005],\u0006 \u0003אחרים אומרים:\u0004 דרך היחיד שיעורה הוא \u0003כדי שיעבור חמור במשאו. אמר רב הונא: הלכה כאחרים. תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003דייני גולה אומרים: שני גמדים\u0004 (אמות) \u0003ומחצה. ואמר רב הונא: הלכה כדייני גולה.\u0004 ותוהים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: הלכה כאחרים!\u0004 ומשיבים: \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא.\u0004","שנינו במשנה כי \u0003דרך הרבים\u0004 רוחבה הוא \u0003שש עשרה אמה.\u0004 ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דרך היחיד\u0004 היא \u0003ארבע אמות. דרך\u0004 שעוברת \u0003מעיר לעיר\u0004 — \u0003שמונה אמות.\u0004"],["\u0003דרך הרבים\u0004 — \u0003שש עשרה אמות. דרך\u0004 המובילה ל\u0003ערי מקלט\u0004 — \u0003שלשים ושתים אמות. אמר רב הונא: מאי קראה\u0004 \u0005[מהו הכתוב]?\u0006 מאין נלמד דבר זה? — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בערי המקלט: \u0003\"תכין לך הדרך\"\u0004 (דברים יט, ג), ויכול היה לומר \u0003\"דרך\"\u0004 ונאמר \u0003\"הדרך\"\u0004 בתוספת ה\"א, ללמד שהדרך הזו כפולה מכל דרך אחרת של הרבים, ולכן היא בת שלושים ושתים אמה.","שנינו במשנה ש\u0003דרך המלך\u0004 \u0003אין לה שיעור.\u0004 ומסבירים: שכן שנינו \u0003שהמלך פורץ גדר לעשות לו דרך ואין ממחין בידו.\u0004","עוד שנינו במשנה: \u0003דרך הקבר אין לה שיעור.\u0004 ומסבירים: וטעמו של דבר — \u0003משום יקרא דשכבא\u0004 \u0005[כבודו של המת]\u0006 על מנת שלא להגביל את מספר המלווים של המת, ולעכב אותם בדרכם.","ועוד שנינו במשנה: \u0003המעמד\u0004 — \u0003דייני ציפורי אמרו:\u0004 מידת שטח \u0003בת ארבע קבין.\u0004 ובענין זה מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אדם \u0003המוכר\u0004 לאחר את \u0003קברו,\u0004 או \u0003דרך קברו,\u0004 או \u0003מקום מעמדו,\u0004 או \u0003בית הספדו\u0004 — \u0003באין בני משפחה\u0004 של המוכר \u0003וקוברין אותו\u0004 שם \u0003על כרחו\u0004 של הקונה, \u0003משום פגם משפחה\u0004 שפגם הוא להם שאחד ממשפחתם אינו נקבר יחד איתם. כיון שהזכרנו ענין המעמדות במשנה מביאים את מה ששנינו בברייתא אחרת, באותו נושא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין פוחתין משבעה מעמדות ומושבות ל\u0004אחר קבורתו של ה\u0003מת, כנגד \"הבל הבלים אמר קהלת הבל הבלים הכל הבל\"\u0004 (קהלת א, ב), שבסך הכל נזכרים שבעה הבלים (\"הבל\" — אחד, \"הבלים\" —","שנים, ובכל הפסוק — שבעה) וכנגדם עושים למת שבע פעמים מעמד ומושב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: היכי עבדי\u0004 \u0005[כיצד עושים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אמר ר' יהודה: ביהודה בראשונה לא היו פוחתין משבעה מעמדות ומושבות למת, כגון\u0004 שהיו אומרים: \u0003\"עמדו יקרים עמודו\", \"שבו יקרים שבו\".\u0004 והיו זזים מעט ממקומם, ושוב עומדים ויושבים. \u0003אמרו לו: אם כן,\u0004 שזהו ענין מעמדות ומושבות, \u0003אף בשבת מותר לעשות כן,\u0004 שהרי אין בו דברי מספד מפורשים.","מסופר: \u0003אחתיה\u0004 \u0005[אחותו]\u0006 של \u0003רמי בר פפא הוה נסיבא ליה\u0004 \u0005[היתה נשואה לו]\u0006 \u0003לרב אויא.\u0004 כאשר \u0003שכיבא\u0004 \u0005[מתה],\u0006 \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003לה מעמד ומושב. אמר רב יוסף, טעה בתרתי\u0004 \u0005[בשני\u0006 דברים\u0005]:\u0006 \u0003טעה, שאין עושין אלא בקרובים,\u0004 שקרובי המשפחה בלבד הם העומדים והיושבים, \u0003והוא עבד\u0004 \u0005[עשה]\u0006 דבר זה \u0003אפילו ברחוקים; וטעה\u0004 טעות אחרת, \u0003שאין עושין אלא ביום ראשון\u0004 של אבל, היום בו נקבר המת, \u0003והוא עבד\u0004 \u0005[עשה]\u0006 \u0003ביום שני.\u0004","\u0003אביי אמר: בהא נמי\u0004 \u0005[בזה גם כן]\u0006 \u0003טעה, שאין עושין\u0004 מעמד ומושב \u0003אלא בבית הקברות,\u0004 \u0003והוא עשה בעיר. רבא אמר: בהא נמי\u0004 \u0005[בזה גם כן]\u0006 \u0003טעה, שאין עושין אלא במקום שנהגו, והתם\u0004 \u0005[ושם]\u0006 \u0003לא נהוג\u0004 \u0005[נהגו].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב יוסף ואביי ממה ששנינו לעיל בברייתא, \u0003אמרו לו: אם כן, אף בשבת מותר לעשות כן; ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שאין עושים מעמד ומושב אלא \u0003בבית הקברות\u0004 (כדברי אביי) \u0003וביום ראשון\u0004 (כדברי רב יוסף), \u0003בית הקברות בשבת מאי בעי\u0004 \u0005[מה\u0006 הוא \u0005עושה]?\u0006 כיצד יכולה להיות קבורת המת ביום השבת? והרי אין קוברים בשבת! ומשיבים: יכול הדבר להיות \u0003בעיר הסמוכה לבית הקברות, דאמטיוהו\u0004 \u0005[שהביאו אותו]\u0006 לקבר \u0003בין השמשות\u0004 של ערב שבת, וכשהחשיך — אם אין במעמד אלא \"עמדו\" ו\"שבו\" — ניתן היה לדעת חכמים לעשות מעמד ומושב.","\u0003המוכר מקום לחברו\u0004 על מנת \u0003לעשות לו קבר, וכן המקבל מחברו\u0004 עבודה בקבלנות \u0003לעשות לו קבר\u0004 — \u0003עושה\u0004 באופן זה: \u0003תוכה של מערה\u0004 שבה קוברים צריך להיות במידותיו \u0003ארבע אמות\u0004 רוחב \u0003על שש\u0004 אמות אורך. \u0003ופותח לתוכה שמונה כוכין\u0004 המיועדים לשים בהם את ארונות המתים, \u0003שלש\u0004 כוכים \u0003מכאן\u0004 (בצידה האחד של המערה, לאורך שש אמות) \u0003ושלש מכאן\u0004 בצד השני, \u0003ושנים מכנגדן\u0004 ממול הכניסה. \u0003וכוכין\u0004 אלה \u0003ארכן ארבע אמות, ורומן\u0004 (גובהן) \u0003שבע\u0004 טפחים,"],["\u0003ורחבן ששה\u0004 טפחים.","\u0003ר' שמעון אומר: עושה תוכה של מערה שש אמות\u0004 רוחב \u0003על שמונה\u0004 אמות אורך, \u0003ופותח לתוכה שלשה עשר כוך,\u0004 כיצד? \u0003ארבעה מכאן\u0004 מן הכותל הצדדי, בן שמונה האמות, \u0003וארבעה מכאן\u0004 בכותל שמולו, \u0003ושלשה מכנגדן\u0004 בכותל שממול הכניסה, \u0003ואחד\u0004 עושה \u0003מימין הפתח ואחד מן השמאל. ו\u0004בנוסף לזה, לדעת הכל","\u0003עושה חצר על פי המערה\u0004 שממנה יורדים למערה, שתהיה \u0003שש\u0004 אמות \u0003על שש, כמלא\u0004 אורך \u0003המטה וקובריה\u0004 (אלה שמוליכים את המיטה או הארון פנימה).","\u0003ופותח לתוכה\u0004 של החצר \u0003שתי מערות, אחת מכאן ואחת מכאן. ר' שמעון אומר:\u0004 פותח לתוך החצר \u0003ארבע\u0004 מערות, \u0003לארבע רוחותיה;\u0004","\u0003רבן שמעון בן גמליאל אומר: הכל לפי הסלע,\u0004 שלפי טיב הסלע בו חוצבים את מערת הקבר צריך למעט או להרבות בבנין הכוכים, שאם הסלע רך צריך לעשות מרחק גדול יותר בין הכוכים, ואם הוא חזק במיוחד ניתן לצמצם את המרחקים בין הכוכים ולהוסיף עוד כוכים.","שנינו במשנה שר' שמעון אמר שמוסיף עוד שני כוכים במערת קבורה, אחד מימין הפתח ואחד מן השמאל, ושואלים: \u0003הני תרי להיכא שדי להו\u0004 \u0005[אותם שניים להיכן\u0006 לאיזה כיוון מפתח המערה הוא \u0005משליך,\u0006 חופר \u0005אותם]?\u0006 \u0003אי לבראי\u0004 \u0005[אם לחוץ],\u0006 כלומר, שחופר אותם לכיוון חצר הקבר, מתחתיה, \u0003הא קמיתדשי להו\u0004 \u0005[הרי הם נידשים,\u0006 נדרסים \u0005להם]\u0006 על ידי הבריות, שכל הבאים לחצר דורכים מעל הקברים, ויש בזה בזיון לנקברים. \u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול, \u0003הא תנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חצר הקבר, העומד בתוכו\u0004 — \u0003טהור,\u0004 משום שאין חשש שמא הוא ניצב מעל קבר, ואילו מכאן יוצא שיש לחשוש, שהרי מתחת לחצר הקבר יש גם כוך קבורה!","\u0003אמר ר' יוסי בר' חנינא: דעביד להו\u0004 \u0005[שעושה אותם],\u0006 את שני הכוכים הללו, בצד הכניסה \u0003כמין נגר\u0004 (עמוד זקוף). כלומר, שאינו חופר אותם כדרך קבורה רגילה, במאוזן, אלא במאונך, לעומק הקרקע, ואין הם מגיעים מתחת לחצר הקבר.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן:\u0004"],["\u0003קבורת חמורים היא זו,\u0004 כלומר, אין קוברים אדם בעמידה!","ומשיבים: \u0003ל\u0004דעת \u0003ר' יוחנן,\u0004 יש להסביר את שיטת ר' שמעון \u0003דעביד להו\u0004 \u0005[שעושה אותם]\u0006 את שני הכוכים שבצד פתח המערה \u0003בקרן זוית,\u0004 כלומר, בפינת המערה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 באופן זה \u0003נגעי כוכין להדדי\u0004 \u0005[נוגעים כוכים זה בזה],\u0006 שאין מספיק מקום בפינה!","\u0003אמר רב אשי: במעמיק\u0004 את הכוכים. כלומר, שאין הם חצובים באותו מיפלס גובה כמו האחרים, אלא למעלה או למטה מהם, כך שאינם נוגעים כלל זה בזה. ומביא ראיה לדבר: \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שמקצת הכוכים עמוקים יותר ואינם באותו גובה, הרי אף בלא אותם שני כוכים נוספים, \u0003ארבע מערות\u0004 בארבע פינות החצר, \u0003לר' שמעון היכי עביד להו\u0004 \u0005[כיצד\u0006 הוא \u0005עושה אותן]?\u0006 \u0003הא קא נגעי\u0004 \u0005[הרי נוגעים]\u0006 ה\u0003כוכין להדדי\u0004 \u0005[זה בזה]\u0006 שהכוכים ממערה אחת בהכרח נוגעים באלה שבמערה הסמוכה לה. \u0003אלא\u0004 על כרחך מדובר \u0003במעמיק,\u0004 וכיון שהגובה שונה, שוב אינם נפגשים. \u0003הכא נמי\u0004 \u0005[כאן\u0006 בעשיית שני הכוכים \u0005גם כן]\u0006 מדובר \u0003במעמיק.\u0004","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר:\u0004 \u0003ארבע מערות לר' שמעון,\u0004 כיצד הן נעשות? — \u0003דעביד להו כי חרותא\u0004 \u0005[שעושה אותן כמו חריות,\u0006 כפות דקלים\u0005]\u0006 שאין העלים יוצאים בקו ישר ניצב לשדרה, אלא באלכסון, ומשום כך אין נפגשים כוכים ממערה זו בכוכים ממערה אחרת, שיש מקום לכל הכוכים.","ומעירים: \u0003והא\u0004 \u0005[וזו]\u0006 שאמר \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא,\u0004 כלומר, לא נכונה. ומדוע? \u0003מכדי\u0004 \u0005[שהרי]\u0006 \u0003כל אמתא בריבועא\u0004 \u0005[אמה ב\u0006צלעות \u0005הריבוע]\u0006 עושה \u0003אמתא ותרי חומשי באלכסונא\u0004 \u0005[אמה ושתי חמישיות באלכסון]\u0006 של אותו הריבוע, אם כן כאשר כותלי שתי מערות ניצבים זה לזה, ואורך כל אחד מהם שמונה אמות, נוצר ריבוע של שמונה על שמונה אמות, \u0003כמה הוי להו\u0004 \u0005[הם ביחד]?\u0006 כלומר, מהו אורך האלכסון של ריבוע בן שמונה אמות — \u0003חד סרי וחומשא\u0004 \u0005[אחת עשרה\u0006 אמות \u0005וחמישית].\u0006 \u0003כוכין כמה הוו\u0004 \u0005[הם]?\u0006 \u0003תמניא\u0004 \u0005[שמונה],\u0006 \u0003תמניא בחד סרי וחומשא היכי משכחת לה\u0004 \u0005[שמונה\u0006 כוכים והרווח שביניהם \u0005באחת עשרה\u0006 אמות \u0005וחומש איך אתה יכול למצוא אותן]?\u0006 \u0003אלא,\u0004 חייבים אנו לומר כי \u0003הא\u0004 \u0005[זו]\u0006 שאמר \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא,\u0004 ובהכרח יש לחזור לפתרונו של רב אשי — במעמיק, שחופר את הכוכים של כל מערה בגבהים שונים.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר בשיטת ר' שמעון, כמו ש\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי\u0004 בשאלה דומה, שמדובר \u0003בניפלי\u0004 \u0005[בנפלים],\u0006 שעושים להם כוכים קטנים ביותר, אם כן \u0003הכא נמי בניפלי\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005בנפלים].\u0006","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003המוצא מת\u0004 שהוא \u0003מושכב כדרכו\u0004 כדרך שקוברים אדם מישראל, והוא רוצה להעבירו למקום אחר — \u0003נוטלו,\u0004 מוציא אותו משם \u0003ו\u0004צריך ליטול עמו גם \u0003את תפוסתו,\u0004 העפר שמסביב ומתחת לו, שיש לשער שאדם מישראל הוא שקבר אותו שם לפי שעה על מנת שיפנוהו משם בעתיד. וכן אם מצא \u0003שנים\u0004 מתים הקבורים כדרך קבורת ישראל — \u0003נוטלן ואת תפוסתן.\u0004"],["אם \u0003מצא שלשה, אם יש ביניהן\u0004 מרחק \u0003מארבע עד שמונה\u0004 אמות — \u0003הרי זו שכונת קברות,\u0004 כלומר, יש לשער שאין זו קבורת ארעי שנועדה לפינוי לאחר מיכן, אלא חלק משכונת קברות שלימה, ומתים אלה שמצא היו קבורים במערת קבורה אחת. \u0003ובודק ממנו ולהלן\u0004 במרחק \u0003עשרים אמה,\u0004 שמא יש שם מערת קבר אחרת. \u0003מצא\u0004 עוד מת \u0003אחד בסוף עשרים אמה\u0004 — \u0003בודק ממנו ולהלן\u0004 עוד \u0003עשרים אמה,\u0004 \u0003שרגלים לדבר,\u0004 כלומר, שיש מקום לשער שבאמת היתה שם שכונת קברים. ועושים זאת כשמצאו מת אחד שם בלבד, למרות \u0003שאילו מתחלה מצאו\u0004 לפני שמצא את השלושה האחרים — היה \u0003נוטלו ואת תפוסתו\u0004 ומוציאו משם. אבל כאן מסתבר ששכונת קברות היא, ואין מוציאים את המתים ממקום קבורתם הקבוע.","ומעתה באים לדון בברייתא זו: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 אם היו המתים \u0003מארבע ועד שמונה\u0004 אמות — הרי זו שכונת קברות, כלומר מערת קבורה. ואנו מבינים כי ארבע אמות הוא רוחב המערה, ושמונה אמות אורכה, ולכן יש לומר שמערת קבורה היא זו. ושואלים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים,\u0006 סתם משנתנו\u0005],\u0006 \u0003הא אמרי\u0004 \u0005[הרי\u0006 הם \u0005אומרים]:\u0006 מערת הקבר היא \u0003ארבע אמות על שש\u0004 ולא על שמונה! \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' שמעון, הא\u0004 \u0005[הרי]\u0006 \u0003אמר:\u0004 שיעור המערה \u0003שש על שמונה!\u0004 ואם כן, מדוע נקבעה כאן מידה שבין ארבעה לשמונה?","ומשיבים: \u0003לעולם\u0004 תפרש שמשנה זו כדעת \u0003ר' שמעון היא, והאי תנא הוא\u0004 \u0005[ו\u0006שיטת \u0005תנא זה היא]\u0006 ששנה אחרת בשם ר' שמעון, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם \u0003מצאן\u0004 את שלושת המתים \u0003רצופין\u0004 (סמוכים זה לזה) \u0003ואין ביניהן מארבע אמות עד שמונה\u0004 אלא פחות — \u0003יש להן תפוסה ואין להן שכונת קברות,\u0004 שהואיל ואין זו דרך שכונת קברות אנו מניחים שאין זו אלא קבורת ארעי. \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: רואין את\u0004 המתים \u0003האמצעיים כאילו אינן\u0004 ומניחים שהם שנקברו שם במקרה, \u0003והשאר מצטרפין מארבע אמות ועד שמונה\u0004 להיחשב שכונת קברות, כלומר, מערת קבורה, שצריך לבדוק אם יש בסמוך לה מערות קבורה נוספות.","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת אותה,\u0006 את הברייתא הזו\u0005]?\u0006 — \u0003כ\u0004דעת \u0003ר' שמעון; אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 \u0003בודק הימנו\u0004 (ממנו) \u0003ולהלן עשרים אמה,\u0004 ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 דעת \u0003ר' שמעון, עשרים ותרתין הויין\u0004 \u0005[עשרים ושתים\u0006 אמות \u0005הן],\u0006 שהוא אורך שתי מערות, כל אחת בת שמונה אמות, וחצר הקבר שביניהן שאורכה שש אמות. \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים],\u0006 \u0003תמני סרי הויין\u0004 \u0005[שמונה עשרה הן],\u0006 שש לכל מערה, ועוד שש לחצר הקבר!","ומעירים: \u0003לעולם\u0004 תפרש שכל הברייתא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, וכגון\u0004 ש\u0003בדק\u0004 את המקום בו מצויים המתים, שיש להניח שהוא מערת קברים, \u0003באלכסונא\u0004 \u0005[באלכסון],\u0006 ואם אורך המערה הוא שש אמות, הרי האלכסון הוא כשמונה אמות.","ושואלים: \u0003ומדהא באלכסונא הא נמי באלכסונא\u0004 \u0005[ומכיון ש\u0006בודק מערה \u0005זו באלכסון זו גם כן\u0006 בודק \u0005באלכסון]\u0006 אם כן, מדוע מסתפק במרחק עשרים אמה, הלא \u0003עשרים ותרתי הויין\u0004 \u0005[ושתים הן]\u0006 שהוא צירוף האלכסונים של שתי מערות והחצר! ואומרים: \u0003חדא באלכסונא אמרינן\u0004 \u0005[\u0006מערה \u0005אחת באלכסון אנו אומרים]\u0006 ובודקים שמא נקבר בצד, אבל \u0003תרי\u0004 \u0005[שתים]\u0006 \u0003באלכסון לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שהרי מעתה אנו יודעים היכן קצה המערה השניה צריך להיות."],["\u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: לעולם\u0004 משנה זו, שבודק עשרים אמה, כשיעור שתי מערות וחצר, שיטת \u0003ר' שמעון היא, ו\u0004אף שלשיטתו מערת קבורה רגילה היא באורך שמונה אמות, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003בניפלי\u0004 \u0005[בנפלים],\u0006 שמשערים שאחת המערות שאליהן הוא מודד היתה מערה שקוברים בה נפלים, והיא קטנה יותר בשיעורה ממערה רגילה, ואף לדעת ר' שמעון שיעורה שש אמות. ואם כן שש של מערה זו, ושש של חצר, ושמונה של מערה אחרת — הרי עשרים אמה.","ושואלים: \u0003ומדהא בניפלי הא נמי בניפלי\u0004 \u0005[ומכיון\u0006 שאנו מניחים \u0005ש\u0006מדובר במערה \u0005זו בנפלים, זו\u0006 המערה הנוספת נאמר שמדובר בה \u0005גם כן בנפלים],\u0006 שהרי באותה מידה ייתכן שגם המערה האחרת עשויה לכך, אם כן \u0003תמני סרי הויין\u0004 \u0005[שמונה עשרה\u0006 אמות \u0005הן],\u0006 שש לכל מערה, ושש לחצר הקבר! ומשיבים: \u0003חדא בניפלי אמרינן\u0004 \u0005[אחת בנפלים אומרים אנו],\u0006 \u0003תרתי בניפלי לא אמרינן\u0004 \u0005[שתים בנפלים אין אנו אומרים],\u0006 שאף שייתכן שתהא מערה אחת כזו — אין להביא בחשבון שתי מערות כאלה הסמוכות זו לזו. בברייתא שהובאה לעיל נשנתה מחלוקת לגבי מתים שנמצאו רצופים וסמוכים זה לזה, שלדעת חכמים אין זו מערת קברים, ולדעת ר' שמעון אין מתחשבים במתים שבאמצע, לפי שנטמנו שם רק לפי שעה.","\u0003ורמי דרבנן אדרבנן\u0004 \u0005[ומשליכים,\u0006 מראים סתירה מדברי \u0005חכמים על\u0006 דברי \u0005חכמים],\u0006 \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' שמעון\u0004 על דברי \u0003ר' שמעון,\u0004","\u0003דתניא\u0004 \u0005[ששנויה]\u0006 משנה: \u0003כרם\u0004 (שיש בו לפחות חמש גפנים) \u0003הנטוע על פחות מארבע אמות\u0004 בין שורת כרמים לחבירתה — \u0003ר' שמעון אומר: אינו\u0004 נחשב \u0003כרם\u0004 לענין איסור כלאיים, אלא רואים את כל הגפנים כעצים בודדים לעצמם. \u0003וחכמים אומרים: הרי זה כרם, ורואין את האמצעים כאילו אינן.\u0004","ומעתה, \u0003קשיא דרבנן אדרבנן\u0004 \u0005[קשה\u0006 מדברי \u0005חכמים על\u0006 דברי \u0005חכמים],\u0006 \u0003וקשיא\u0004 \u0005[וקשה]\u0006 מדברי \u0003ר' שמעון\u0004 על דברי \u0003ר' שמעון,\u0004 שהרי בענין גפנים דעתם הפוכה! ומתרצים: מדברי \u0003ר' שמעון\u0004 על דברי \u0003ר' שמעון לא קשיא\u0004 \u0005[קשה],\u0006 \u0003התם לא נטעי אינשי אדעתא ליעקר\u0004 \u0005[שם,\u0006 בכרם, \u0005אין אנשים נוטעים על דעת לעקור],\u0006 והואיל והוא נטוע בצפיפות כזו — אין זה נחשב כרם, \u0003הכא זימנין דמיתרמא ליה\u0004 \u0005[כאן,\u0006 לענין קבורה, \u0005פעמים שמזדמן לו]\u0006 לקבור \u0003בין השמשות\u0004 שאין זמן לחפש מקום אחר, \u0003ומיקרי ומנחי ליה\u0004 \u0005[\u0006\u0005ומזדמן ומניחים אותו\u0006 כך\u0005]\u0006 על מנת להוציאו ולקוברו אחר כך כראוי.","","\u0003דרבנן אדרבנן נמי לא קשיא\u0004 \u0005[\u0006מדברי \u0005חכמים על\u0006 דברי \u0005חכמים גם כן אינו קשה]:\u0006 \u0003הכא\u0004 \u0005[כאן,\u0006 לענין קבורה\u0005]\u0006 \u0003כיון דמינול\u0004 \u0005[ש\u0006הוא \u0005מתנוול]\u0006 אם קוברים אותו בצפיפות \u0003לא מקרי\u0004 \u0005[אינו נקרא]\u0006 \u0003קבר, התם\u0004 \u0005[שם]\u0006 בכרם \u0003מימר אמר\u0004 \u0005[אומר הוא]\u0006 הנוטע: \u0003הי מינייהו דשפיר\u0004 \u0005[זה מהם ש\u0006יהיה, יצמח, \u0005יפה]\u0006 — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003ודלא שפיר\u0004 \u0005[ושאינו יפה]\u0006 — \u0003ליהוי לציבי\u0004 \u0005[שיהיה,\u0006 אעקרנו ואשתמש בו, \u0005לעצים,\u0006 להסקה\u0005],\u0006 ואין מחשיבים גפנים אלו שבאמצע לגפנים, אלא לעצים סתם, והרי זה כרם לכל דבר.","","\u0003האומר לחבירו \"בית כור עפר אני מוכר לך\",\u0004 אם \u0003היו שם\u0004 בקרקע הנמכרת \u0003נקעים\u0004 (סדקים ובקיעים) שהיו \u0003עמוקים עשרה טפחים, או\u0004 שהיו שם \u0003סלעים\u0004 ה\u0003גבוהין\u0004 מן הקרקע \u0003עשרה טפחים\u0004 — \u0003אינן נמדדין עמה,\u0004 אלא צריך לתת לו שטח של בית כור חוץ מאותם נקעים וסלעים. אם היה שיעורם של הנקעים או הסלעים \u0003פחות מכאן,\u0004 כלומר, מעשרה טפחים — \u0003נמדדין עמה. ואם אמר לו \"כבית כור עפר\",\u0004 ולא אמר לו \"בית כור\", \u0003אפילו היו שם נקעים עמוקים יותר מעשרה טפחים, או סלעים גבוהין יותר מעשרה טפחים\u0004 — \u0003הרי אלו נמדדין עמה.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת ערכין: \u0003המקדיש שדהו\u0004 (שדה אחוזתו) \u0003בשעת היובל,\u0004 כלומר, בזמן שהיה היובל נוהג — \u0003נותן לו\u0004 לגזבר ההקדש, בפדיון השדה, \u0003ל\u0004כל \u0003בית זרע חומר שעורים,\u0004 דהיינו, שטח שזורעים בו כור של שעורים, \u0003חמשים שקל כסף\u0004 עבור כל שנות היובל, שזה הסכום הקצוב לזה בתורה (ויקרא כז, טז). אם \u0003היו שם\u0004 בשטח השדה \u0003נקעים עמוקים עשרה טפחים, או סלעים גבוהין עשרה טפחים\u0004 —"],["\u0003אין נמדדין עמה,\u0004 אם היו \u0003פחות מכאן,\u0004 מעשרה טפחים — \u0003נמדדין עמה.\u0004","ושואלים על כך: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003ליקדשו באנפי נפשייהו\u0004 \u0005[שיקדשו\u0006 נקעים אלה \u0005בפני עצמם]!\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003כיון דלא הוי\u0004 \u0005[שאינו]\u0006 שטח של \u0003בית כור\u0004 שלם הריהם \u0003לא קדשי\u0004 \u0005[מתקדשים],\u0006","\u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הפסוק \"ואם גאל יגאל את השדה המקדיש אותו\" (ויקרא כז, יט): \u0003\"שדה\" מה תלמוד לומר?\u0004 והרי בשדה אנו עוסקים באותם פסוקים, ודי לומר \"אותו\"! \u0003לפי שנאמר: \"זרע חמר שערים בחמשים שקל כסף\"\u0004 (ויקרא כז, טז), יכול הייתי לומר: \u0003אין לי\u0004 דין זה \u0003אלא\u0004 כ\u0003שהקדיש בענין הזה,\u0004 כלומר, דווקא שטח זריעת חומר (בית כור) שעורים,","\u0003מנין לרבות\u0004 גם כשהקדיש \u0003לתך\u0004 (שטח של חצי בית כור), \u0003וחצי לתך, סאה, תרקב וחצי תרקב?\u0004 — \u0003תלמוד לומר: \"שדה\", מכל מקום,\u0004 משמע שניתן להקדיש גם שטח קטן בפני עצמו!","\u0003אמר רב עוקבא בר חמא: הכא\u0004 \u0005[כאן]\u0006 \u0003בנקעים מלאים מים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003בני זריעה נינהו\u0004 \u0005[הם]\u0006 ולכן אינם קדשים, שהרי נאמר \"והיה ערכך לפי זרעו\" (ויקרא כז, טז). ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק\u0006 \u0005גם כן\u0006 הסבר זה\u0005],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 נקעים \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003סלעים,\u0004 שהם בוודאי אינם ראוים לזריעה, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר בנקעים מלאים מים, ומשום שאינם מקום זרע, \u0003אפילו פחות מכאן נמי\u0004 \u0005[גם כן],\u0006 גם אם היו נבדלים בגובהם מן השדה פחות מעשרה טפחים, לא יקדשו! ומשיבים: כאשר ההבדל בגובה הוא קטן יותר, \u0003הנהו \"נגאני דארעא\" מיקרו\u0004 \u0005[אלה\u0006 הנקעים \u0005\"\u0006\u0005חריצי הקרקע\"\u0006 הם \u0005נקראים],\u0006 והסלעים \u0003\"שדרי דארעא\" מיקרו\u0004 \u0005[\"שדראות הארץ\"\u0006 הם \u0005נקראים]\u0006 ואינם נבדלים לעצמם.","ושואלים: למדנו לענין הקדש, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 לענין מיקח וממכר, ששנינו שנקעים עמוקים עשרה טפחים אינם נמדדים עם הקרקע, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם הוא דווקא כשהנקעים מלאים מים? \u0003אמר רב פפא: אף על פי שאין\u0004 הם \u0003מלאים מים\u0004 אין הם נחשבים בכלל השדה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003אין אדם\u0004 הקונה שדה \u0003רוצה שיתן מעותיו ב\u0004קניית \u0003מקום אחד, ויראו לו כשנים ושלשה מקומות,\u0004 לפי שאין גובהם שווה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: והא דומיא\u0004 \u0005[והרי בדומה]\u0006 ל\u0003סלעים קתני\u0004 \u0005[שנה]\u0006 נקעים, \u0003מה סלעים דלאו\u0004 \u0005[שלא]\u0006 \u0003בני זריעה נינהו\u0004 \u0005[הם],\u0006 \u0003אף הני נמי\u0004 \u0005[אלה,\u0006 הנקעים, \u0005גם כן]\u0006 מדובר במקרה \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003בני זריעה נינהו\u0004 \u0005[הם],\u0006 אבל אם ניתנים להיזרע, גם אם גובהם שונה הריהם בכלל המכירה! ומשיבים: \u0003כי קתני דומיא\u0004 \u0005[כאשר שנה\u0006 נקעים \u0005בדומה]\u0006 ל\u0003סלעים\u0004 — הרי זה על מה ששנינו \u0003פחות מכאן,\u0004 פחות מעשרה טפחים, לומר שבמקרה זה גם אם אינם נזרעים הריהם נמדדים עם השדה.","שנינו שאם היו סלעים ונקעים \u0003פחות מכאן\u0004 מעשרה טפחים הם \u0003נמדדין עמה.\u0004 ומסבירים, \u0003אמר ר' יצחק: טרשים שאמרו\u0004 שנמדדים עמה — דווקא כשהם בשיעור \u0003בית\u0004 (שטח זריעה של) \u0003ארבעת קבין\u0004 בתוך בית כור. \u0003אמר רב עוקבא בר חמא: והוא\u0004 דווקא כ\u0003שמובלעין\u0004 שהיו מפוזרים ארבעה קבים אלו \u0003ב\u0004תוך שטח של \u0003חמשת קבין. רב חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן: והוא\u0004 דווקא כ\u0003שמובלעין\u0004 מפוזרים \u0003ברובה של\u0004 ה\u0003שדה.\u0004","על אותה הלכה שהביא בשם ר' יוחנן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חייא בר אבא:\u0004 אם היו \u0003רובן\u0004 של הטרשים \u0003במעוטה\u0004 של השדה, או \u0003מעוטן\u0004 של הטרשים \u0003ברובה, מהו?\u0004 האם הולכים אחר מיעוט השדה, ואומרים שהוא מלא טרשים, או שמא דנים אחר השדה כולו, ובסך הכל מובלעים הטרשים ברובו של השדה? שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004"],["היו הסלעים הללו ברובה של השדה, אבל היו מפוזרים \u0003כשיר\u0004 (כטבעת), \u0003מהו?\u0004 או שהיו עומדים \u0003כשורה, מהו?\u0004 וכן אם היו מפוזרים בצורת \u0003איצטדינין\u0004 כעין זוית, \u0003מהו?\u0004 בצורת \u0003דרך עקלתון\u0004 (בקו בלתי ישר, מפותל) \u0003מהו?\u0004 על כל אחת מן השאלות הללו לא נמצא פתרון ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אם היה\u0004 בשדה \u0003סלע יחידי, אפילו\u0004 אם מידתו היא \u0003כל שהוא\u0004 — \u0003אין נמדד עמה. ואם היה\u0004 הסלע \u0003סמוך למצר, אפילו\u0004 היה גובהו \u0003כל שהוא\u0004 — \u0003אין נמדד עמה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם היה \u0003מופסק עפר בינתים\u0004 ולא היה ממש נוגע במצר, \u0003מהו\u0004 הדין? אף שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 היה \u0003עפר מלמטה וצונמא\u0004 \u0005[סלע]\u0006 \u0003למעלה,\u0004 או \u0003עפר מלמעלה וצונמא מלמטה, מהו\u0004 הדין? אף לשאלה זו לא נמצא פתרון ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","אם אמר המוכר: \u0003\"בית כור עפר אני מוכר לך מדה בחבל\",\u0004 כלומר, במידה מדוייקת, הנמדדת בחבל מידה, אם \u0003פיחת\u0004 ממידה זו \u0003כל שהוא\u0004 — \u0003ינכה\u0004 המוכר מן המחיר, ויחזיר לקונה כסף כשווי הפחת, ואם \u0003הותיר כל שהוא\u0004 על מידה זו — \u0003יחזיר\u0004 הקונה. \u0003ואם אמר\u0004 שהוא מוכר \u0003\"\u0004בית כור \u0003הן חסר הן יתר\", אפילו פיחת\u0004 בשיעור \u0003רובע\u0004 (רביעית הקב) \u0003ל\u0004כל \u0003סאה\u0004 (כלומר, בשיעור של אחד מעשרים וארבעה), \u0003או הותיר רובע לסאה\u0004 — \u0003הגיעו,\u0004 נגמר המיקח כמות שהוא, כיון שאמר לו המוכר לקונה מתחילה שאין זה בהכרח בית כור מדוייק. ואולם, אם היה ההבדל \u0003יותר מכאן,\u0004 כלומר, מרובע לסאה — \u0003יעשה חשבון\u0004 בשווי ההפרש.","וכשהקונה מחזיר למוכר את המותר, \u0003מה הוא מחזיר לו?\u0004 — \u0003מעות.\u0004 ומעירים: \u0003ואם רצה\u0004 המוכר — \u0003מחזיר לו\u0004 הקונה \u0003קרקע. ולמה אמרו\u0004 ש\u0003מחזיר לו מעות?\u0004 — כדי \u0003לייפות כחו של מוכר,\u0004 שיכול לדרוש מעות ואינו חייב לקבל ממנו דווקא את הקרקע היתירה. אלא \u0003שאם שייר בשדה בית תשעה קבין, ובגינה בית חצי קב,\u0004 או \u0003כדברי ר' עקיבא בית רובע\u0004 קב — \u0003מחזיר לו את הקרקע\u0004 ואינו יכול לדרוש מעות. ומעירים: \u0003ו\u0004כשהותיר יותר מרובע, ומחזיר, \u0003לא את הרובע בלבד הוא מחזיר, אלא את כל המותר,\u0004 שכיון שנזקק להחזיר — יתן לו במידה מדוייקת.","במשנה דובר על שני מקרים במכירת בית כור עפר: כשאמר לו \"מידה בחבל\" — שמחזיר לו כל שהוא, ומן הצד האחר כשאמר \"הן חסר הן יתר\" — שעד רובע לסאה הגיעו. ומעתה, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לתלמידי בית המדרש\u0005]\u0006 מקרה אחר: אמר לו \u0003\"בית כור\" סתמא\u0004 \u0005[סתם],\u0006 שלא אמר לו לא \"מידה בחבל\" ולא \"הן חסר הן יתר\", \u0003מאי\u0004 \u0005[מה]\u0006 הדין? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנה: \u0003\"בית כור עפר אני מוכר לך מדה בחבל\",\u0004"],["אם נמצא שנתן לו \u0003פחות כל שהוא\u0004 — \u0003ינכה, יתר כל שהוא\u0004 — \u0003יחזיר,\u0004 ומכאן נדייק: \u0003הא סתמא\u0004 \u0005[הרי\u0006 אם אמר \u0005סתם]\u0006 ולא פירש דבריו — \u0003כ\"הן חסר הן יתר\" דמי\u0004 \u0005[נחשב].\u0006","ודוחים בראיה הפוכה: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003ואם אמר לו \"הן חסר הן יתר\", אפילו פיחת רובע לסאה או הותיר רובע לסאה\u0004 — \u0003הגיעו,\u0004 ונדייק: \u0003הא סתמא\u0004 \u0005[הרי בסתם]\u0006 שלא פירש לו כך — \u0003כ\"מדה בחבל\" דמי\u0004 \u0005[נחשב]!\u0006 \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מזו,\u0006 ממשנתנו, \u0005אין לשמוע ממנה]\u0006 בדרך הדיוק, שאפשר לדייק בה, כפי שראינו, לשני הצדדים.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא, אמר לו המוכר לקונה: \u0003\"בית כור עפר אני מוכר לך\",\u0004 או שאמר לו: \u0003\"כבית כור עפר אני מוכר לך\",\u0004 או \u0003\"הן חסר הן יתר אני מוכר לך\", אפילו פיחת רובע לסאה או הותיר רובע לסאה\u0004 — \u0003הגיעו; אלמא\u0004 \u0005[מכאן יוצא]\u0006 כי \u0003סתמא נמי\u0004 \u0005[בסתם גם כן]\u0006 \u0003כ\"הן חסר הן יתר\" דמי\u0004 \u0005[נחשב].\u0006 ודוחים: \u0003התם פרושי קא מפרש\u0004 \u0005[שם מפרש הוא]\u0006 את דבריו, וכך צריך להבינם: \u0003איזהו בית כור שהיא כבית כור\u0004 ולא בדיוק בית כור? \u0003כגון\u0004 ש\u0003אמר ליה\u0004 \u0005[שאומר לו]\u0006 \"בית כור \u0003הן חסר הן יתר\".\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על תירוץ זה \u0003רב אשי: אם כן,\u0004 מה שנאמר \u0003\"אני מוכר לך\" \"אני מוכר לך\" למה לי?\u0004 ומכאן משמע שאין זה מכר אחד, אלא מקרים שונים של מכירה. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא\u0006 \u0005תלמד מכאן]\u0006 כי \u0003סתמא נמי\u0004 \u0005[סתם גם כן]\u0006 \u0003כ\"הן חסר הן יתר\" דמי\u0004 \u0005[נחשב]?\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","שנינו במשנה שכשהקונה מחזיר את המותר למוכר \u0003מהו מחזיר לו?\u0004 — \u0003מעות,\u0004 ואם רצה מחזיר לו קרקע, ולמה אמרו שמחזיר לו מעות — לייפות כוחו של מוכר. כלומר, חכמים נתנו למוכר את הבחירה אם לקבל מעות, הגם שבכך הם מכריחים את הקונה לקנות תוספת זאת. ושואלים: וכי \u0003ליפות\u0004 את \u0003כחו של\u0004 \u0003מוכר אמרינן\u0004 \u0005[אומרים אנו],\u0006 ואילו \u0003ליפות\u0004 את \u0003כחו של לוקח לא אמרינן\u0004 \u0005[אין אנו אומרים]?\u0006","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 אם \u0003פיחת\u0004 המוכר \u0003שבעת קבין ומחצה לכור,\u0004 כשיעור רבע הקב לכל בית סאה (שהכור מכיל שלושים סאים), \u0003או הותיר שבעת קבין ומחצה לכור\u0004 — \u0003הגיעו,\u0004 נתקיים המיקח כפי שהוא. היה ההפרש \u0003יותר מכאן\u0004 — \u0003כופין את המוכר למכור ואת הלוקח ליקח\u0004 (לקנות),","משמע שמייפים גם את כוחו של הקונה, ומחייבים את המוכר למכור את הקרקע ולקבל מעות, אם הקונה רוצה בה! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 אין מדובר במקרה שהקונה רוצה בקרקע היתירה, אלא \u0003כגון דהוה יקירא מעיקרא וזל השתא\u0004 \u0005[שהיתה הקרקע יקרה מתחילה,\u0006 בשעת המכירה, \u0005והוזלה עכשיו]\u0006 והמוכר רוצה לקבל מעות תמורת הקרקע היתירה, אלא שרצונו שחשבון המעות שיקבל יהיה על פי המחיר הקודם, היקר, \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]\u0006 למוכר, בשם הקונה: \u0003אי ארעא יהבת\u0004 \u0005[אם קרקע אתה נותן]\u0006 \u0003לי\u0004 ורצונך לקבל מעות — \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי כזולא דהשתא\u0004 \u0005[כמו\u0006 המחיר \u0005הזול של עכשיו],\u0006 והיא הכפייה שכופים אנו את המוכר.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשהוא נותן לו\u0004 מעות תמורת הקרקע היתירה — \u0003נותן לו כשער שלקח\u0004 (קנה) \u0003ממנו!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003כגון דהוה זולא מעיקרא ויקרא\u0004 \u0005[שהיתה זולה מתחילה והתייקרה]\u0006 \u0003לה השתא\u0004 \u0005[עכשיו],\u0006 שאם רצונו של המוכר לקבל מעות דווקא, כופים אותו למוכרו לפי השער הזול, של זמן הקניה.","שנינו במשנה \u0003שאם שייר בשדה בית תשעה קבין\u0004 או בגינה בית חצי קב, ולדעת ר' עקיבא בית רובע, מחזיר הקונה את גוף הקרקע ואין המוכר יכול לתבוע דמים במקום הקרקע. \u0003אמר רב הונא: תשעה קבין שאמרו, ואפילו בבקעה גדולה\u0004 ששטחה כמה וכמה כורים, אם סך כל עודפי הייתור נצטברו לכדי שדה חשוב (תשעה קבים), רשאי הקונה להחזיר למוכר קרקע אפילו היתה התוספת פחות מרובע לכל בית סאה.","\u0003ורב נחמן אמר: נותן,\u0004 מחשב, \u0003שבעת קבין ומחצה לכל כור וכור\u0004 (שהוא רובע לבית סאה), וכל זמן שהיה ההפרש לפי שיעור זה הרי זו מחילה, גם אם מצטבר סך כל ההפרש בכל הבקעה ליותר מתשעה קבים."],["\u0003ואי\u0004 \u0005[ו\u0006אולם \u0005אם]\u0006 לאחר חישוב זה \u0003איכא\u0004 \u0005[יש]\u0006 \u0003מילתא יתירא\u0004 \u0005[דבר יתר]\u0006 קרקע יתירה נוספת על רובע לבית סאה, \u0003דהוי\u0004 \u0005[שהוא]\u0006 מצטרף \u0003ל\u0004הפרש של \u0003תשעת קבין\u0004 — \u0003הדרי\u0004 \u0005[חוזרים]\u0006 כל החלקים הנוספים, גם אלה שכשלעצמם היתה בהם מחילה מתחילה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן:\u0004 שנינו במשנה \u0003שאם שייר בשדה בית תשעת קבין\u0004 מחזיר לו קרקע; \u0003לאו\u0004 \u0005[האם לא]\u0006 מדובר גם במקרה \u0003דזבין ליה\u0004 \u0005[שמכר לו]\u0006 \u0003כוריים,\u0004 שטח של שני כורים? משמע שגם אם לא היה ההבדל יותר מרובע לבית סאה (שהרי רובע לבית סאה בכוריים מגיע לחמישה עשר קבים) — אין הדבר תלוי אלא בכך שיש שם תשעה קבים! ודחה רב נחמן: \u0003לא,\u0004 מדובר \u0003דזבין ליה\u0004 \u0005[שמכר לו]\u0006 דווקא בית \u0003כור.\u0004","ועוד הקשה רבא לרב נחמן, הרי שנינו: \u0003ובגנה\u0004 אם שייר \u0003בית חצי קב\u0004 מחזיר קרקע; \u0003לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן \u0003דזבין ליה\u0004 \u0005[שמכר לו]\u0006 אפילו בית \u0003סאתים?\u0004 ונמצא שמחזיר לו קרקע בכל אופן, אם יש בה שיעור גינה, אפילו ההבדל אינו אלא רובע הקב לבית סאה! ודחה רב נחמן: \u0003לא,\u0004 מדובר באופן \u0003דזבין ליה\u0004 \u0005[שמכר לו]\u0006 בית \u0003סאה\u0004 ושיעור ההבדל גדול מזה.","ועוד הקשה רבא לרב נחמן ממה ששנינו: \u0003וכדברי ר' עקיבא\u0004 אם שייר בגינה \u0003בית רובע\u0004 מחזיר קרקע; \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דזבין ליה\u0004 \u0005[שמכר לו]\u0006 בית \u0003סאה\u0004 שההבדל אינו עולה על רובע לבית סאה, ולמרות זאת אם יש בו שיעור גינה — מחזיר קרקע! ודחה רב נחמן: \u0003לא,\u0004 מדובר דווקא \u0003דזבין ליה\u0004 \u0005[שמכר לו]\u0006 \u0003חצי סאה,\u0004 ששיעור ההבדל גדול מכך.","על האמור במשנה, שאם היתה זו גינה, די בכך ששייר בית חצי קב, כדי שיוכל הקונה להחזיר קרקע, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 אם מכר לו \u0003שדה\u0004 ונמצאה גדולה ממה שסיכמו ביניהם, \u0003ו\u0004קודם שהחזיר הקונה את התוספת \u0003נעשית גנה,\u0004 או \u0003גנה ונעשית שדה, מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם דנים את התוספת כדין שדה, ואם אין שם בית תשעה קבים רשאי המוכר לדרוש דמים, או שמא דנים את המקום כדין גינה, ואם יש במותר בית חצי קב — רשאי הקונה לתת לו קרקע? שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אם היה\u0004 השדה שנמכר \u0003סמוך לשדהו\u0004 של המוכר, \u0003אפילו\u0004 הותיר \u0003כל שהוא\u0004 — \u0003מחזיר לו\u0004 הקונה \u0003קרקע,\u0004 ואין המוכר יכול לדרוש דמים, שהרי אינו מפסיד על ידי החזרת מידת קרקע קטנה, שהריהו מעבד אותו יחד עם שדהו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 אם היה \u0003בור\u0004 נמצא בין השדות, \u0003מהו שתפסיק\u0004 לענין זה? וכן אם היתה \u0003אמת המים, מהו שתפסיק?\u0004 וכן \u0003דרך הרבים, מהו שתפסיק?\u0004 וכן \u0003ריכבא דדיקלא\u0004 \u0005[שורה של דקלים],\u0006 \u0003מהו שתפסיק?\u0004 לאף אחת מן השאלות הללו לא נמצא פתרון ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה: \u0003ולא את הרובע בלבד מחזיר לו, אלא\u0004 את \u0003כל\u0004 \u0003המותר.\u0004 ותוהים: \u0003כלפי לייא\u0004 \u0005[לאן הוא פונה]?!\u0006 כלומר, הפוכים הדברים, שהרי את המותר הוא מחזיר גם כאשר הרבעים נשארים ברשות הלוקח! \u0003תאני\u0004 \u0005[שנה]\u0006 \u0003רבין בר רב נחמן\u0004 כך את המשנה: \u0003לא את המותר בלבד מחזיר לו, אלא את כל הרבעין כולן,\u0004 שאם נתחייב להחזיר את המותר אינו מחזיר רק את המותר זה בלבד, אלא מחזיר לו את כל מה שהוסיף על המידה שקצבו מתחילה ביניהם.","אמר המוכר לקונה: \u0003\"מדה בחבל אני מוכר לך הן חסר הן יתר\",\u0004 שנמצא שאמר שני תנאים סותרים — \u0003בטל\u0004 מה שאמר \u0003\"הן חסר הן יתר\"\u0004 את מה שאמר \u0003\"מדה בחבל\",\u0004 ואם לא היתה שם תוספת יתר על רובע לבית סאה — נתקיים המיקח כפי שהוא. אם אמר לו: \u0003\"הן חסר הן יתר מדה בחבל\"\u0004 —"],["\u0003בטל\u0004 התנאי \u0003\"מדה בחבל\"\u0004 את התנאי \u0003\"הן חסר הן יתר\",\u0004 שבכל מקרה הולכים אחר לשון אחרון שאמר, אלו \u0003דברי בן ננס.\u0004","\u0003אמר ר' אבא בר ממל אמר רב: חולקין עליו חביריו על בן ננס\u0004 ואינם מסכימים עימו שהולכים אחר הלשון האחרון. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב בכך? הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה: \u0003מעשה בציפורי, באחד ששכר מרחץ מחבירו\u0004 והוסכם ביניהם שיהיה מחיר השכירות \u0003ב\u0004שיעור \u0003שנים עשר זהובים לשנה, דינר זהב לחדש,\u0004","\u0003ובא מעשה\u0004 זה \u0003לפני רבן שמעון בן גמליאל ולפני ר' יוסי\u0004 לדון לגבי שנה מעוברת, האם חודש העיבור הוא בכלל \"שנים עשר זהובים לשנה\", או שצריך לשלם תוספת עבורו, שהרי אמר ב\"דינר זהב לחודש\", \u0003ואמרו: יחלוקו את חדש העיבור\u0004 משמע שבמקום כזה שאומר שני לשונות סותרים פסקו חכמים שספק הוא, ויחלוקו!","ומתרצים: \u0003אי מהתם\u0004 \u0005[אם משם]\u0006 בלבד לא הייתי יודע שחלוקים חכמים על בן ננס בכל מקרה, שכן \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שאמרו שיחלוקו, משום \u0003דאיכא למימר מיהדר קא הדר ביה\u0004 \u0005[ש\u0006מצד אחד \u0005יש\u0006 מקום \u0005לומר\u0006 ש\u0005הוא חוזר בו]\u0006 מדיבור ראשון, וקוצב מחיר של דינר זהב לחודש, \u0003ו\u0004מן הצד האחר \u0003איכא למימר פרושי קא מפרש\u0004 \u0005[יש\u0006 מקום \u0005לומר\u0006 ש\u0005הוא מפרש]\u0006 את הדברים שאמר תחילה. שאין כוונתו להתייחס כלל לחודש העיבור, אלא רצונו לומר שהתשלום לשנה לא יהא בסוף השנה, אלא דינר זהב בכל חודש, ומכיון שיש ספק במשמעות דבריו — יחלוקו, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במשנתנו שב\u0003ודאי קא הדר ביה\u0004 \u0005[חזר בו]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 חולקים חכמים בזה, ומודים הם לבן ננס, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחולקים עליו.","ובדומה למה שהובא קודם לכן בשם רב, \u0003אמר רב יהודה אמר שמואל:\u0004 משנתנו \u0003זו\u0004 היא כ\u0003דברי בן ננס\u0004 שהולך אחר לשון אחרון, \u0003אבל חכמים אומרים:\u0004 \u0003הלך\u0004 (לך) \u0003אחר פחות שבלשונות,\u0004 כלומר, יש ללכת תמיד אחר הלשון הכוללת פחות מהאחרת, ולפי הכלל שהמוציא מחבירו עליו הראיה.","ותוהים: מכלל הלשון \u0003\"זו\u0004 דברי בן ננס \u0003\"\u0004שאמר שמואל נראה שזו היא שיטת בן ננס, \u0003ו\u0004אולם שמואל עצמו \u0003לא סבירא ליה\u0004 \u0005[סבור הוא]\u0006 כן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם],\u0006 האומר לחבירו: \u0003\"כור\u0004 (מידה בת שלושים סאים) תבואה, \u0003בשלשים\u0004 סלע \u0003אני מוכר לך\"\u0004 — \u0003יכול לחזור בו\u0004 מן המכר \u0003אפילו בסאה האחרונה\u0004 שמודד, שהרי התנה למכור כור שלם, וכל זמן שלא מדד כור שלם עדיין לא חלה המכירה.","אבל אם אמר לו \u0003\"כור בשלשים,\u0004 כל \u0003סאה בסלע אני מוכר לך\"\u0004 — \u0003ראשון ראשון\u0004 מן הסאים שמדד \u0003קנה.\u0004 משמע ששמואל סבור שהולכים אחר לשון אחרון, \"סאה בסלע\", שלפיה מכר כל סאה לעצמה! \u0003אלא\u0004 צריך להסביר שמה שאמר שמואל \"זו דברי בן ננס\", משמעו: \u0003\"זו\" וסבירא ליה\u0004 \u0005[וסבור הוא]\u0006 כשיטה זו, שהולכים אחר לשון אחרון.","ואף על כך שואלים: \u0003ומי סבירא ליה\u0004 \u0005[והאם סבור הוא\u0006 כך\u0005]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל:\u0004 מה שפסקו חכמים בענין המשכיר מרחץ ואמר לשוכר שהוא משכיר אותו בשנים עשר זהובים לשנה, דינר לחודש, שיחלקו ביניהם את חודש העיבור, הרי דווקא \u0003ב\u0004מקרה ש\u0003בא\u0004 המשכיר לתבוע את דמי השכירות \u0003באמצע החדש עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003אבל\u0004 במקרה ש\u0003בא בתחלת החדש\u0004 — הרי \u0003כולו למשכיר\u0004 שתובע את שכרו, שהרי הוא המוחזק בקרקע. וכן אם בא \u0003בסוף החדש\u0004 — \u0003כולו לשוכר,\u0004 שהרי הוא מוחזק בכסף. ומכאן משמע שלדעת שמואל אין הולכים אחר לשון אחרון, אלא רואים זאת כספק שקול הנידון לפי הכלל של \"המוציא מחבירו עליו הראיה\"!"],["\u0003אלא לעולם\u0004 תפרש שמה ששמואל אמר \u0003\"זו\"\u0004 כוונתו: \u0003ו\u0004הוא עצמו \u0003לא סבירא ליה\u0004 \u0005[סבור]\u0006 כן, ש\"תפוס לשון אחרון\", ולדעתו כאשר יש שני לשונות סותרים ספק הוא, כחכמים. \u0003והתם\u0004 \u0005[ושם\u0006 בענין חודש השכירות הנוסף\u0005]\u0006 \u0003טעמא מאי\u0004 \u0005[מהו הטעם]\u0006 למה שאמר שאם בתחילת החודש — כולו למשכיר, בסופו — כולו לשוכר? \u0003משום דתפיס\u0004 \u0005[ש\u0006הוא \u0005תופס],\u0006 ומספק משאירים את הדבר בידי המוחזק בו.","\u0003הכא\u0004 \u0003נמי\u0004 \u0005[כאן\u0006 \u0005גם כן]\u0006 בענין מכירת התבואה, כשאמר \"כור בשלושים, סאה בסלע\" \u0003הא תפיס\u0004 \u0005[הריהו תופס],\u0006 שמה שכבר נכנס בקופתו של הקונה — הריהו כשלו ואין המוכר יכול לחזור בו, ולפיכך ראשון ראשון קנה, ולא משום \"תפוס לשון אחרון\".","באותו נושא \u0003אמר רב הונא, אמרי בי\u0004 \u0005[\u0006היו \u0005אומרים\u0006 החכמים \u0005בבית]\u0006 \u0003רב:\u0004 אם אמר אדם \u0003\"איסתרא מאה מעי\u0004 \u0005[מעות]\u0006 \u0003\",\u0004 ואיסתרא הוא מטבע ששוויו תשעים ושש מעות, אנו אומרים שהתכוון ל\u0003מאה מעי\u0004 \u0005[מעות].\u0006 אם אמר הפוך: \u0003\"מאה מעי איסתרא\"\u0004 — אנו אומרים שהתכוון ל\u0003איסתרא.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 רב \u0005בכך],\u0006 האם את הכלל ש\u0003תפוס לשון אחרון? הא\u0004 \u0005[הרי\u0006 כבר\u0005]\u0006 \u0003אמרה רב חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר רב:\u0004 \u0003אי הואי התם\u0004 \u0005[אם הייתי שם]\u0006 בבית המדרש, כשנדונה הבעיה לגבי תשלום שכירות המרחץ בחודש העיבור, \u0003הוה יהיבנא כוליה\u0004 \u0005[הייתי נותן\u0006 את \u0005הכל]\u0006 את דמי שכירות כל החודש \u0003למשכיר,\u0004 משום שבסוף דבריו אמר \"דינר זהב לחודש\"!","ומשיבים: בכל זאת צריכים שני הדינים להיאמר, ואין ללמוד זה מזה, שכן \u0003אי איתמר הא\u0004 \u0005[אם היתה נאמרת\u0006 הלכה \u0005זו]\u0006 ב\"איסתרא מאה מעי\" בלבד, \u0003ולא איתמר הא\u0004 \u0005[נאמרה זו\u0006 במרחץ\u0005],\u0006 \u0003הוה אמינא מיהדר קא הדר ביה\u0004 \u0005[הייתי אומר\u0006 ש\u0005הוא חוזר בו]\u0006 מדיבורו הראשון (\"איסתרא\") בדיבורו השני (\"מאה מעי\"), שהרי הדברים סותרים זה את זה, ומשום כך הולכים אחר לשון אחרון. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בענין חודש העיבור \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי רק \u0003פרושי קא מפרש\u0004 \u0005[מפרש הוא]\u0006 בדבריו האחרונים למה התכוון מתחילה, ואין כאן הוכחה שהולכים בכלל אחר לשון אחרון\u0005,\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב, שככלל הולכים אחר לשון אחרון."],["המוכר לחבירו שדה, ואמר לו שמוכר לו בית כור \u0003בסימניו\u0004 המסויימים שיש בו \u0003ובמצריו\u0004 (בגבולותיו), שהראה לו אותם, והתברר אחר כך שלא היה שטח השדה בדיוק בית כור, כיון שמוכר לו שדה מסויים ומוגדר (ולא סתם \"בית כור\"), אין מדקדקים במידתו כמו במכר רגיל. ולכן אם היה ההבדל \u0003פחות משתות\u0004 (שישית) — \u0003הגיעו\u0004 ונגמר המיקח כמות שהוא. אם היה ההפרש יותר מזה, כגון: רבע, חמישית, \u0003עד שתות\u0004 — \u0003ינכה\u0004 את ההפרש מן המחיר.","ובענין הלכה שאינה מפורשת במשנתנו \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים, \u0003רב הונא אמר: שתות\u0004 עצמה דינה \u0003כפחות משתות\u0004 ונגמר המיקח. ו\u0003רב יהודה אמר: שתות\u0004 דינה \u0003כיותר משתות\u0004 ומנכה מהמחיר.","ומסבירים את טעמיהם: \u0003רב הונא\u0004 ש\u0003אמר\u0004 שדין \u0003שתות כפחות משתות, הכי קאמר\u0004 \u0005[כך אמר\u0006 במשנה\u0005],\u0006 כך יש להבינה: \u0003פחות משתות ושתות בכלל\u0004 זה — \u0003הגיעו, יותר משתות\u0004 — \u0003ינכה. רב יהודה\u0004 ש\u0003אמר\u0004 שדין \u0003שתות כיותר משתות, הכי קאמר\u0004 \u0005[כך אמר\u0006 במשנה\u0005]\u0006 כך יש להבינה: \u0003פחות משתות\u0004 — \u0003הגיעו, עד שתות ושתות בכלל\u0004 — \u0003ינכה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב הונא ממה ששנינו בברייתא: המוכר בית כור \u0003בסימניו ובמצריו,\u0004 אם \u0003פיחת שתות או הותיר שתות\u0004 — \u0003הרי הוא כשום\u0004 (הערכת) \u0003הדיינין\u0004 שמעריכים נכסים כדי למוכרם אחר כך במכירה פומבית, ו\u0003הגיעו; והא\u0004 \u0005[והרי]\u0006 \u0003שום הדיינין,\u0004 שדין \u0003שתות\u0004 עצמה \u0003כיותר משתות הוא\u0004 ובטלה ההערכה, וקשה לרב הונא!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רב הונא: ו\u0004הרי אף \u0003לטעמיך\u0004 \u0005[לטעמך,\u0006 לשיטתך\u0005]\u0006 קשה הדבר, הלא \u0003\"הגיעו\" קא תני\u0004 \u0005[שנה]\u0006 בברייתא, והרי שהמיקח קיים כמות שהוא! \u0003אלא\u0004 יש לומר, שההשוואה של דין זה לשום הדיינים אינה לכל דבר, אלא כך צריך להבין: \u0003כשום הדיינין ולא כשום הדיינין, כשום הדיינין ל\u0004ענין שנקודת הגבול היא \u0003שתות, ולא כשום הדיינין\u0004 — ש\u0003אילו התם\u0004 \u0005[שם]\u0006 \u0003בטל מקח, ואילו הכא\u0004 \u0005[כאן]\u0006 — \u0003הגיעו\u0004 ונגמר המיקח.","מסופר: \u0003רב פפא זבן ארעא מההוא גברא\u0004 \u0005[קנה קרקע מאדם אחד],\u0006"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר: \u0003הויא עשרין גריוי\u0004 \u0005[הריהי\u0006 בת שטח זריעה של \u0005עשרים סאה],\u0006 \u0003משחיה\u0004 \u0005[מדד\u0006 רב פפא \u0005אותה]\u0006 \u0003ולא הואי\u0004 \u0005[היתה]\u0006 \u0003אלא חמיסרא\u0004 \u0005[\u0006בת \u0005חמש עשרה\u0006 סאה\u0005].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב פפא \u0005לפני]\u0006 \u0003אביי\u0004 לתבוע את המוכר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003סברת וקבילת\u0004 \u0005[ידעת וקבלת]\u0006 את הקרקע כמות שהיא.","הקשה לו: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 גם כשאמר לו בסימניו ובמצריו, מכל מקום \u0003פחות משתות\u0004 — \u0003הגיעו, עד שתות\u0004 — \u0003ינכה,\u0004 וכאן ההבדל הוא יותר משתות! ענה לו אביי: \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005במקום]\u0006 ש\u0003לא קים ליה בגוה\u0004 \u0005[מוחזק לו בה],\u0006 שאין הקונה מכיר את הקרקע הנמכרת לו \u0003אבל היכא דקים ליה בגוה\u0004 \u0005[במקום שמוחזק לו בה]\u0006 — \u0003סבר וקביל\u0004 \u0005[ידע וקיבל]\u0006 כמות שהיא.","ושוב חזר והקשה לו רב פפא: \u0003והא עשרין\u0004 \u0005[והרי עשרים]\u0006 \u0003אמר לי,\u0004 ואינה עשרים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כוונתו היתה \u0003דעדיפא כעשרין\u0004 \u0005[ש\u0006היא \u0005טובה\u0006 ומשובחת ועושה פירות \u0005כמו\u0006 קרקע אחרת בת \u0005עשרים].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: האחין שחלקו\u0004 ביניהם את ירושתם על ידי הגרלה, שלאחר שחילקו את הירושה למספר חלקים כמספר האחים, הפילו גורל איזה חלק יקבל כל אחד, \u0003כיון שעלה גורל לאחד מהן\u0004 — \u0003קנו כולם\u0004 ואינם יכולים לחזור בהם. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 הלא אין הגורל מעשה של קנין! \u0003אמר ר' אלעזר:\u0004 דינו \u0003כתחלת\u0004 חלוקת \u0003ארץ ישראל\u0004 לשבטי ישראל, \u0003מה תחלה\u0004 היתה החלוקה \u0003בגורל, אף כאן בגורל.\u0004","ותוהים, \u0003אי\u0004 \u0005[אם]\u0006 אתה משווה חלוקת אחים לחלוקת ארץ ישראל, נאמר גם כן בהשוואה: \u0003מה להלן\u0004 בחלוקת הארץ היא היתה \u0003בקלפי ואורים ותומים, אף כאן\u0004 יהיה הגורל קובע רק \u0003בקלפי ואורים ותומים! אמר רב אשי: בההוא\u0004 \u0005[באותה]\u0006 \u0003הנאה\u0004 שיש להם, לאחים, \u0003דקא צייתי להדדי\u0004 \u0005[שמצייתים זה לזה]\u0006 ומסכימים לעשות גורל, \u0003גמרי ומקנו להדדי\u0004 \u0005[גומרים ומקנים זה לזה],\u0006 ולכן נגמרת החלוקה עם יציאת גורל ראשון.","ובענין דומה למה ששנינו במשנה \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003שני אחין שחלקו\u0004 בירושה את נכסי אביהם, \u0003ו\u0004לאחר מכן \u0003בא להן אח ממדינת הים\u0004 וכגון שלא ידעו קודם על קיומו, \u0003רב אמר: בטלה מחלוקת\u0004 (החלוקה) וחוזרים ומחלקים את הנכסים בין שלושתם. \u0003ושמואל אמר: מקמצין,\u0004 כלומר, כל אחד נוטל מחלקו ונותן לאח השלישי את חלקו היחסי. ומבררים את שיטותיהם של רב ושמואל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: ל\u0004דעת \u0003רב\u0004 ש\u0003אמר בטלה מחלוקת, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הדר דינא\u0004 \u0005[חוזר הדין],\u0006 כלומר, שאם נעשה מעשה שהתברר אחר כך שהיתה בו טעות — מתבטל הדין כולו, \u0003אלא מעתה, הני בי תלתא דקיימי\u0004 \u0005[אותם שלושה שעומדים]\u0006 בשותפות, \u0003ואזול בי תרי מינייהו ופלוג\u0004 \u0005[והלכו שניים\u0006 \u0005מהם וחלקו]\u0006 את הרכוש, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003בטלה מחלוקת\u0004 וצריכים לחזור ולחלק שוב בין שלושתם?","ודחה רב נחמן: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 והרי יש הבדל ברור בין המקרים: \u0003התם נחיתי אדעתא דבי תלתא מעיקרא\u0004 \u0005[שם,\u0006 במקרה שאתה מביא, \u0005ירדו,\u0006 נכנסו לחלוקה \u0005על דעת ש\u0006הם \u0005שלושה מתחילה],\u0006 והיה צורך רק לברר מה חלקו של כל אחד, ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 בדברי רב, \u0003לא נחיתי אדעתא דבי תלתא מעיקרא\u0004 \u0005[ירדו על דעת ש\u0006הם \u0005שלושה מתחילה]\u0006 שהרי חשבו שרק שנים הם.","ולשיטת שמואל, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: לשמואל\u0004 ש\u0003אמר מקמצין, למימרא\u0004 \u0005[האם\u0006 יש \u0005לומר]\u0006 ללמוד מכאן שלשיטתו אומרים \u0003דקם דינא\u0004 \u0005[שעומד,\u0006 קיים, \u0005הדין]\u0006 גם אם היתה בו טעות? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 המוכר תבואה לחבירו, ואמר \u0003\"כור\u0004 (שלושים סאים) \u0003בשלשים\u0004 דינרים \u0003אני מוכר לך\"\u0004 — \u0003יכול לחזור בו\u0004 כל זמן שמודד, \u0003אפילו בסאה האחרונה,\u0004 אבל אם אמר לו \u0003\"כור בשלשים,\u0004 כל \u0003סאה בסלע אני מוכר לך\"\u0004 — \u0003ראשון ראשון\u0004 מן הסאים שמדד לתוך הכלי — \u0003קנה,\u0004 ואם עומד הדין בעינו, מדוע יוכל לחזור בו כאשר אמר \"כור בשלושים\" וכבר החל למדוד?"],["ומשיבים: \u0003התם עבוד רבנן מילתא\u0004 \u0005[שם עשו חכמים דבר]\u0006 \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 \u0003למוכר וניחא ליה\u0004 \u0005[ונוח לו]\u0006 \u0003ללוקח\u0004 שפעמים שמשתנה המחיר, ושניהם רוצים שלא יגמר המיקח מיד כדי שיוכלו לחזור בהם, וטעם זה אינו קיים במקרה של חלוקת נכסים.","ועוד בענין דומה \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003אחין שחלקו\u0004 ביניהם את ירושת אביהם, \u0003ובא בעל חוב\u0004 של אביהם \u0003ונטל חלקו של אחד מהן\u0004 לפרעון אותה הלוואה, \u0003רב אמר: בטלה מחלוקת\u0004 (החלוקה) כולה, והאחים חוזרים וחולקים ביניהם את הנשאר, \u0003ושמואל אמר: ויתר\u0004 (הפסיד) זה שלקחו ממנו את השדה, \u0003ורב אסי אמר:\u0004 אותו אח שלקחו ממנו את חלקו \u0003נוטל רביע\u0004 (רבע) \u0003בקרקע ורביע במעות.\u0004","ומסבירים את השיטות: \u0003רב אמר בטלה מחלוקת, קא סבר\u0004 \u0005[סבור הוא]:\u0006 \u0003האחין שחלקו יורשין הן\u0004 כאילו לא חלקו, וחוב האב חל על כולם בשווה, ולכן אם נטל בעל החוב רק מאחד מהם, הרי הוא כמשלם את חוב כולם, ולכן חוזרים וחולקים ביניהם את הנשאר.","\u0003ושמואל אמר ויתר, קא סבר\u0004 \u0005[סבור הוא]:\u0006 \u0003האחין שחלקו לקוחות הוו\u0004 \u0005[הם],\u0006 דינם כאנשים שקונים זה מזה, \u0003וכלוקח שלא באחריות דמי\u0004 \u0005[נחשבים\u0006 הם\u0005],\u0006 וקניה שלא באחריות משמעה שגם אם בעלי חוב של המוכר גובים (\"טורפים\") ממנו את הנכסים שהיו משועבדים להם — אין המוכר חייב לשלם לו.","\u0003רב אסי מספקא ליה אי\u0004 \u0005[מסופק לו אם]\u0006 \u0003יורשין הוו\u0004 \u0005[הם],\u0006 או \u0003אי\u0004 \u0005[אם]\u0006 \u0003לקוחות הוו\u0004 \u0005[לקוחות הם],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003נוטל רביע,\u0004 דהיינו מחצית מן הסכום שנותר — \u0003בקרקע\u0004 כדין יורש, \u0003ורביע\u0004 רשאי אחיו לתת לו \u0003במעות\u0004 כדין לוקח באחריות, שמקבל תשלום עבור מה שהפסיד.","\u0003אמר רב פפא: הלכתא בכל הני שמעתתא\u0004 \u0005[ההלכה בכל השמועות,\u0006 הסוגיות, \u0005הללו]\u0006 שחלקו ביניהם רב ושמואל: \u0003מקמצין,\u0004 וכדברי שמואל, שלא בטלה החלוקה, אלא שלוקחים מחלקם של האחים עד שמשלימים את חלקו של האח האחר. \u0003אמימר אמר:\u0004 ההלכה בכל אלה היא ש\u0003בטלה מחלוקת,\u0004 כדעת רב. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 למעשה\u0005]:\u0006 \u0003בטלה מחלוקת\u0004 כדעת רב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה שירדו לשום\u0004 (להעריך) קרקע מסויימת, כדי לגבות ממנה חוב, \u0003אחד\u0004 מהם \u0003אומר\u0004 ששוויה \u0003במנה\u0004 (מאה דינרים) \u0003ושנים\u0004 האחרים \u0003אומרים במאתים,\u0004 או \u0003אחד אומר במאתים ושנים אומרים במנה\u0004 — \u0003בטל יחיד במיעוטו\u0004 ועושים כדעת הרבים.","אם היה \u0003אחד אומר במנה, ואחד אומר בעשרים\u0004 סלעים, שהם שמונים דינרים (שארבעה דינרים יש בסלע), \u0003ואחד אומר בשלשים\u0004 סלעים, שהם מאה ועשרים דינרים — \u0003נדון במנה\u0004 שהוא הממוצע בין שניהם — שהם עשרים סלעים. \u0003ר' אליעזר בר' צדוק אומר:\u0004 במקרה זה \u0003נדון בתשעים,\u0004 כאשר מבואר להלן. \u0003אחרים אומרים: עושין שומא\u0004 (הערכה) \u0003ביניהן\u0004 בכמה שתי הדעות הקיצוניות חלוקות זה מזה, \u0003ומשלשין\u0004 מחלקים לשלושה את ההבדל ומוסיפים אותו לסכום הקטן יותר.","ומבארים את השיטות: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003נדון במנה,\u0004 הוא סבור שיש ללכת אחרי \u0003מילתא מציעתא\u0004 \u0005[הדבר הממוצע]\u0006 בין שתי ההערכות הקיצוניות, \u0003ר' אליעזר בר' צדוק אומר נדון בתשעים,\u0004 ומדוע? \u0003קא סבר\u0004 \u0005[סבור הוא\u0006 כך\u0005]:\u0006 \u0003הא ארעא\u0004 \u0005[קרקע זו]\u0006"],["\u0003תשעין\u0004 \u0005[תשעים]\u0006 דינרים \u0003שוה, והאי דקאמר\u0004 \u0005[וזה שאומר]\u0006 \u0003עשרים\u0004 סלעים, שהם שמונים — משום \u0003דקא טעי\u0004 \u0005[שטועה הוא]\u0006 בהפרש \u0003עשרה\u0004 דינרים \u0003לאחוריה\u0004 \u0005[לאחוריו],\u0006 כלומר, נמוך מדי, \u0003והאי דקא אמר\u0004 \u0005[וזה שאומר]\u0006 \u0003מנה\u0004 — \u0003קא טעי\u0004 \u0005[טועה]\u0006 \u0003עשרה לקמיה\u0004 \u0005[לפניו],\u0006 כלומר, גבוה מדי, ולכן לוקחים את הסכום הממוצע בין שני אלה.","ומקשים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 תאמר כך: \u0003האי ארעא\u0004 \u0005[קרקע זו]\u0006 \u0003מאה ועשרה\u0004 דינרים \u0003שויא\u0004 \u0005[שווה],\u0006 \u0003והאי דקאמר\u0004 \u0005[וזה שאומר]\u0006 \u0003מנה\u0004 — \u0003קא טעי\u0004 \u0005[טועה הוא]\u0006 \u0003עשרה לאחוריה\u0004 \u0005[לאחוריו],\u0006 כלומר, מפחית עשרה מן המחיר, \u0003והאי דקאמר\u0004 \u0005[וזה שאומר]\u0006 \u0003שלשים\u0004 שהם מאה ועשרים דינר — \u0003קא טעי עשרה לקמיה\u0004 \u0005[טועה הוא עשרה לפניו]\u0006 שמוסיף על המחיר, ואם כן צריכים לקבוע סכום זה של מאה ועשרה בממוצע! ומשיבים: \u0003נקוט מיהת תרי קמאי\u0004 \u0005[תפוס על כל פנים\u0006 את \u0005שני הראשונים]\u0006 \u0003בידך,\u0004 ש\u0003מתורת מנה לא מפקי ליה\u0004 \u0005[אינם מוציאים אותו],\u0006 ששניהם סבורים ששווה מנה או פחות מכן.","ועוד שנינו בברייתא: \u0003אחרים אומרים עושין שומא ביניהן ומשלשין,\u0004 ומסבירים: \u0003קא סברי\u0004 \u0005[סבורים הם\u0006 אחרים\u0005]\u0006 כך: \u0003האי ארעא תשעין ותלתא ותילתא שויא\u0004 \u0005[קרקע זו תשעים ושלושה ושליש שווה\u0006 באמת\u0005],\u0006 \u0003האי דקא אמר\u0004 \u0005[זה שאומר]\u0006 \u0003עשרים\u0004 (שמונים דינר) — \u0003קא טעי תליסר ותילתא לאחוריה\u0004 \u0005[טועה הוא\u0006 ב\u0005שלושה עשר ושליש לאחוריו],\u0006 כלומר, בפחות, \u0003והאי דקאמר\u0004 \u0005[וזה שאומר]\u0006 \u0003מנה\u0004 — \u0003קא טעי תליסר ותילתא לקמיה\u0004 \u0005[טועה הוא\u0006 ב\u0005שלושה עשר ושליש לפניו].\u0006 \u0003ובדין הוא דלימא טפי\u0004 \u0005[שיאמר יותר],\u0006 כלומר, שלפי חשבון זה היה צריך לומר שהיא שווה מאה ושש ושני שליש, \u0003והאי דלא קאמר\u0004 \u0005[וזה שאינו אומר\u0006 כך\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003מיסתאי דקא מטפינא כולי האי אחבראי\u0004 \u0005[די לי שאני מוסיף כל כך על חברי]\u0006 שאמר שמונים, ולכן מפחית כאן מן הסכום שמעריך.","ומקשים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 אפשר לומר כי \u0003הא ארעא מאה ותליסר ותלתא שויא\u0004 \u0005[קרקע זו מאה ושלושה עשר ושליש שווה],\u0006 \u0003האי דקאמר\u0004 \u0005[זה שאומר]\u0006 \u0003מנה\u0004 — \u0003קא טעי תליסר ותלתא לאחוריה\u0004 \u0005[טועה הוא שלושה עשר ושליש לאחוריו]\u0006 שהפחית, \u0003והאי דקאמר\u0004 \u0005[וזה שאומר]\u0006 \u0003שלשים\u0004 (כלומר, מאה ועשרים דינרים) — \u0003טעי תליסר ותלתא לקמיה\u0004 \u0005[טועה\u0006 הוא ב\u0005שלושה עשר ושליש לפניו].\u0006 \u0003ובדין הוא דקאמר טפי\u0004 \u0005[שיאמר יותר]\u0006 שלפי חשבון זה היה צריך לקבוע מאה עשרים וששה ושני שליש, אלא \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003מיסתאי דקא מטפינא כולי האי אחבראי\u0004 \u0005[די לי שאני מוסיף כל כך\u0006 הרבה \u0005על חברי]!\u0006 ומשיבים: \u0003נקוט מיהת תרי קמאי\u0004 \u0005[תפוס על כל פנים\u0006 את \u0003שני הראשונים]\u0004 \u0003בידך,\u0004 ש\u0003מתורת מאה לא מפקי ליה\u0004 \u0005[אינם מוציאים אותו].\u0006","ובפסק ההלכה בענין זה \u0003אמר רב הונא: הלכה כאחרים\u0004 שעושים שומה ביניהם ומשלשים. \u0003אמר רב אשי: טעמא\u0004 \u0005[\u0006את \u0005הטעם]\u0006 של \u0003אחרים לא ידעינן\u0004 \u0005[איננו יודעים,\u0006 מבינים\u0005]\u0006 \u0003הלכתא עבדינן כוותייהו\u0004 \u0005[הלכה אנו עושים כמותם]?!\u0006 וכדעת אחרים שבברייתא \u0003תנו\u0004 \u0005[שנו]\u0006 \u0003דייני גולה: עושין שומא ביניהן ומשלשין. אמר רב הונא: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כדייני גולה. אמר רב אשי:\u0004 \u0003טעמא\u0004 \u0005[\u0006את \u0005הטעם]\u0006 של \u0003דייני גולה\u0004 \u0003לא ידעינן\u0004 \u0005[אין אנו יודעים],\u0006 \u0003הלכתא עבדינן כוותייהו\u0004 \u0005[הלכה אנו עושים כמותם]?!\u0006","\u0003האומר לחבירו \"חצי שדה אני מוכר לך\",\u0004 ולא פירש איזה — \u0003משמנין\u0004 (עושים שומה) \u0003ביניהן\u0004 לפי ערכו של כל אחד מחלקי השדה, \u0003ונוטל\u0004 הקונה \u0003חצי שדהו.\u0004 אמר לו המוכר: \u0003\"חציה\u0004 ש\u0003ב\u0004צד \u0003דרום אני מוכר לך\"\u0004 — \u0003משמנין ביניהן,\u0004 מעריכים את ההפרש שבין שני החצאים, הצפוני והדרומי, \u0003ונוטל חציה בדרום. והוא מקבל עליו מקום הגדר\u0004 שבין החלקות, שהוא בונה בחלקו. וכן עושה בחלקו \u0003חריץ ובן חריץ\u0004 (תעלות קטנות לשמירת השדה מן החיות). \u0003וכמה הוא חריץ? ששה טפחים, ובן חריץ? שלשה\u0004 טפחים.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 המוכר לחבירו חצי שדה — ה\u0003לוקח נוטל\u0004 את החלק ה\u0003כחוש שבו,\u0004 חצי השדה הפחות בטיבו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא לר' יוחנן: והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"משמנין ביניהן\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 שנוטלים חלקים שווים בערכם, וכיצד אתה אומר שהלוקח מקבל את החלק הכחוש! \u0003אמר ליה\u0004 \u0005[לו]\u0006 בלשון קינתור: \u0003אדאכלת כפנייתא\u0004 \u0005[עד שאתה אכלת תמרים]\u0006 \u0003בבבל\u0004 כאשר היית שם ולא עיינת כראוי — \u0003תרגימנא מסיפא\u0004 \u0005[הסברנו\u0006 את הדבר","\u0005מן הסוף\u0006 של המשנה\u0005],\u0006 שמשם מוכח כדברי, \u0003דקתני סיפא\u0004 \u0005[ששנינו בסופה]:\u0006 \u0003\"חציה בדרום אני מוכר לך\"\u0004 — \u0003משמנין ביניהן ונוטל חציה בדרום,\u0004 ואם מבינים את הדברים כמשמעם יש לתמוה: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003משמנין ביניהן? והא\u0004 \u0005[והרי]\u0006 \u0003חציה בדרום אמר ליה\u0004 \u0005[לו]\u0006 ויתן לו את חציה הדרומי, ומה מקום לשומה והשוואת ערך! \u0003אלא\u0004 חייב אתה לומר שהדבר מורכב יותר, וכי הכוונה היא \u0003לדמי\u0004 \u0005[לדמים],\u0006 כלומר, הלוקח נוטל את חציה בדרום, אלא שהמוכר צריך לפצות אותו בכסף על הבדל השווי שיש בין חצאי השדה, ולפי זה \u0003הכא נמי לדמי\u0004 \u0005[כאן גם כן\u0006 הכוונה \u0005לדמים],\u0006 שהלוקח מקבל את החלק הכחוש, אבל המוכר מוסיף לו לפי הערכה, כמה ששווה ההבדל בין חצאי השדה השונים.","שנינו במשנה שהקונה \u0003מקבל עליו מקום גדר\u0004 חריץ ובן חריץ. \u0003תאנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003חריץ\u0004 עושים \u0003מבחוץ, ובן חריץ מבפנים\u0004 סמוך יותר אל השדה, \u0003וזה וזה\u0004 עושים אותם \u0003אחורי גדר,\u0004"],["\u0003כדי שלא תהא חיה קופצת\u0004 על הגדר, ונכנסת לשדה ומזיקה. ושואלים: \u0003ולעביד\u0004 \u0005[ושיעשה]\u0006 \u0003חריץ\u0004 גדול \u0003ולא לעביד\u0004 \u0005[יעשו]\u0006 \u0003בן חריץ!\u0004 ומשיבים: \u0003איידי דרווח\u0004 \u0005[מתוך שמרווח]\u0006 החריץ, \u0003קיימא בגויה וקפצה\u0004 \u0005[עומדת\u0006 החיה \u0005בתוכו וקופצת]\u0006 על הגדר. ואומרים: אם כן \u0003ולעביד\u0004 \u0005[ושיעשה]\u0006 \u0003בן חריץ ולא לעביד\u0004 \u0005[יעשה]\u0006 \u0003חריץ!\u0004 ומשיבים: \u0003איידי דקטין, קיימא אשפתיה וקפצה\u0004 \u0005[מתוך ש\u0006הוא \u0005קטן,\u0006 צר, \u0005עומדת על שפתו\u0006 של בן החריץ \u0005וקופצת]\u0006 מעבר לו. ומסבירים עוד בברייתא: \u0003וכמה\u0004 המרחק \u0003בין חריץ לבן חריץ? טפח.\u0004","","במשנה זו מבוארים סדרי ירושת אדם מישראל שמת, וסדר זה אינו תלוי בקירבה המשפחתית שבין המת לקרוביו בלבד, אלא נלמד מן הכתובים. ויש בדבר כמה אופנים: \u0003יש נוחלין ומנחילין,\u0004 יש קרובי המשפחה הנוחלים ירושה מקרוביהם וגם מנחילים להם את ירושתם כשמתו, \u0003ויש נוחלין\u0004 מקרובים מסויימים \u0003ו\u0004אולם \u0003לא מנחילין\u0004 להם, ויש \u0003מנחילין ולא נוחלין,\u0004 וכן יש כאלו, שלמרות שהם קרובי משפחה, בכל זאת הם \u0003לא נוחלין ולא מנחילין\u0004 אלה את אלה.","ומפרשים, \u0003ואלו נוחלין ומנחילין: האב את הבנים, והבנים את האב, והאחין מן האב\u0004 — \u0003נוחלין ומנחילין.\u0004 ואולם \u0003האיש את אמו,\u0004 \u0003והאיש את אשתו, ובני אחיות\u0004 של אדם שמת, שהוא אחי אימותיהם — כל אלו \u0003נוחלין ולא מנחילין,\u0004 שכן \u0003האשה את בניה,\u0004 \u0003והאשה את בעלה, ואחי האם\u0004 — כל אלו \u0003מנחילין ולא נוחלין. והאחין מן האם\u0004 ולא מן האב, למרות שיש ביניהם קירבת דם — \u0003לא נוחלין ולא מנחילין\u0004 שלענין נחלה אין קירבתם נחשבת כקירבה.","בתחילה מבררים את לשונה וסדרה של המשנה. ושואלים: \u0003מאי שנא דקתני\u0004 \u0005[מה שונה ששנה]\u0006 \u0003\"האב את הבנים\" ברישא\u0004 \u0005[בתחילה]?\u0006 \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"הבנים את האב\" ברישא\u0004 \u0005[בתחילה]!\u0006 ויש מקום להצעה זו משני טעמים: \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד],\u0006 \u0003דאתחולי בפורענותא לא מתחלינן\u0004 \u0005[שלהתחיל בפורענות אין אנו מתחילים],\u0006 שפטירתם של בנים בחיי האב (\"האב את הבנים\") פורענות היא, אבל דרך העולם שהבנים יורשים את אבותיהם, ובזה ראוי לפתוח."],["\u0003ועוד,\u0004 שכן בתורה נזכרת תחילה ירושת הבן את אביו, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 בפרשת הנחלות: \u0003\"איש כי ימות ובן אין לו\u0004 והעברתם את נחלתו...\u0003\"\u0004 (במדבר כז, ח)!","\u0003ו\u0004משיבים: ה\u0003תנא\u0004 של משנתנו שסידר את הדברים כך — \u0003איידי דאתיא ליה מדרשא\u0004 \u0005[מתוך שבאה,\u0006 נלמדה, \u0005לו\u0006 ירושת האב את הבן \u0005מדרשה]\u0006 ואינה מפורשת בתורה — \u0003חביבא ליה\u0004 \u0005[חביבה לו],\u0006 משום החידוש שיש בה, ולכן מקדים אותה.","\u0003ומאי דרשא\u0004 \u0005[ומה הדרשה]\u0006 שיש בזה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \"ונתתם את נחלתו לשארו הקרוב אליו\" (במדבר כז, יא): \u0003\"שארו\"\u0004 — \u0003זה האב, מלמד שהאב קודם\u0004 בירושה \u0003לאחין\u0004 (של המת), \u0003יכול יהא קודם\u0004 בירושה גם \u0003לבן? תלמוד לומר: \"הקרב\"\u0004 (במדבר כז, יא), לומר: \u0003קרוב קרוב קודם,\u0004 והבן הוא הקרוב יותר.","ושואלים: \u0003ומה ראית לרבות את הבן\u0004 ולומר שהוא קרוב יותר מאשר האב, \u0003ולהוציא את האח?\u0004 ומשיבים: \u0003מרבה אני את הבן, שכן קם תחת אביו ליעדה,\u0004 שהקונה אמה עבריה מאביה יכול לקדשה לאשה, לעצמו או לבנו, אבל אינו יכול ליעדה לאחיו. \u0003ו\u0004כן \u0003לשדה אחוזה,\u0004 שלענין פדיון שדה אחוזה שהוקדש, נחשב בנו של המקדיש כאב עצמו, ואם פדה את השדה אינו חוזר להקדש בשנת היובל, מה שאין כן אם פדה את השדה אחיו של המקדיש.","ומקשים: \u0003אדרבה\u0004 \u0005[להיפך]\u0006 יש צד לומר ש\u0003מרבה אני את האח, שכן קם תחת אחיו ליבום\u0004 אשתו, מה שאין כן הבן! ודוחים: \u0003כלום יש יבום אלא במקום שאין בן, הא\u0004 \u0005[הרי]\u0006 \u0003במקום שיש בן אין יבום\u0004 לפי שאביו כאילו קיים, ואם כן קירבת הבן גדולה יותר.","על דרשה זו שואלים: \u0003טעמא דאיכא האי פירכא\u0004 \u0005[הטעם,\u0006 דווקא משום \u0005שיש פירכה זו]\u0006 שבמקום שיש בן אין יבום, לכן למדים שיש להקדים את הבן, \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כך]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003אח עדיף\u0004 מבן, ויקדימהו בירושה; ואולם \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הראיה שהבן קודם אף בלא פירכה זו, מכך"],["\u0003דהכא תרתי והכא חדא\u0004 \u0005[שכאן\u0006 יש \u0005שתי\u0006 הוכחות \u0005וכאן\u0006 יש רק \u0005אחת]!\u0006","ומשיבים: דין \u0003שדה אחוזה גופה\u0004 \u0005[עצמו]\u0006 שדווקא הבן הוא העומד במקום האב בפדיון השדה, \u0003מהאי טעמא\u0004 \u0005[מטעם זה\u0006 עצמו\u0005]\u0006 \u0003הוא דקא קיימא ליה\u0004 \u0005[שעומד,\u0006 שמוכח \u0005לו]\u0006 \u0003לתנא,\u0004 שכן דין זה לא נאמר במפורש בתורה, וכדי להוכיח שהבן פודה ולא האח, למרות שהאח עומד תחת המת ליבום, אומרים שם: \u0003כלום יש יבום אלא במקום שאין בן, הא\u0004 \u0005[הרי]\u0006 אם \u0003יש בן אין יבום.\u0004 ואם כן ההוכחה מדין שדה אחוזה אינה הוכחה נוספת, שהרי אינה עומדת לעצמה. ומקשים על הדרשה מצד אחר: מדוע נקדים את האב רק לאחים?","\u0003אימא\u0004 \u0005[אמור]\u0006 שיקדם גם לבת, ודרוש בדרך אחרת: \u0003\"שארו\"\u0004 — \u0003זה האב, מלמד שהאב קודם לבת\u0004 בירושה; \u0003יכול יקדים לבן? תלמוד לומר: \"הקרוב\"\u0004 — \u0003קרוב קרוב קודם!\u0004","ודוחים: \u0003כיון\u0004 ש\u0003לענין יבום\u0004 — \u0003בן ובת כי הדדי נינהו\u0004 \u0005[זה כמו זה הם],\u0006 שאם יש למת בן או בת אין דין יבום, \u0003לענין נחלה נמי\u0004 \u0005[גם כן]\u0006 \u0003בן ובת כי הדדי נינהו\u0004 \u0005[זה כמו זה הם]\u0006 ושניהם קודמים לאב.","ומקשים עוד, \u0003ואימא\u0004 \u0005[ואמור]\u0006 דרשה אחרת ובאופן זה: \u0003\"שארו\"\u0004 — \u0003זה\u0004 \u0003האב, מלמד שהאב קודם לאחי האב; יכול יקדים\u0004 \u0003לאחין? תלמוד לומר: \"הקרוב\"\u0004 — \u0003קרוב קרוב קודם!\u0004","ודוחים: \u0003אחי האב לא צריכי קרא\u0004 \u0005[אינם צריכים כתוב]\u0006 מיוחד ללמד שהאב קודם להם בירושה, כי \u0003אחי האב מכח מאן קא אתו\u0004 \u0005[מכח מי הם באים],\u0006 מכח מה באה ירושתם? \u0003מכח אב\u0004 שהרי הם באים לרשת את בן אחיהם מכוחו של אחיהם. וכי יכול אתה לומר שכאשר \u0003קאי\u0004 \u0005[עומד,\u0006 קיים\u0005]\u0006 ה\u0003אב\u0004 עצמו \u0003קא ירתי\u0004 \u0005[יורשים]\u0006 \u0003אחי האב?\u0004 ונמצא למסקנה שאין אפשרות לדרוש את הכתובים בדרך זו, אלא כדי ללמד שהאב (\"שארו\") קודם לאחים.","ומקשים: וכיצד אפשר לדרוש כך? \u0003והא קראי לאו הכי כתיבי\u0004 \u0005[והרי הכתובים לא כך נאמרו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"...ואם אין לו אחים ונתתם את נחלתו לאחי אביו\", ורק אחר כך: \u0003\"ואם אין אחים לאביו\u0004 ונתתם את נחלתו לשארו הקרוב אליו\u0003\"\u0004 (במדבר כז, יא)! ומשיבים: \u0003קראי\u0004 \u0005[הכתובים]\u0006 \u0003שלא כסדרן כתיבי\u0004 \u0005[כתובים]\u0006 כפי שהסברנו, שהרי לא ייתכן שאחי האב יקדמו לאב, ומשום כך יכולים אנו לדרוש בדרך זו.","על הלכה זו שהאב קודם לאחים, ודרשוה מ\"שארו\", מעירים: \u0003והאי תנא מייתי לה מהכא\u0004 \u0005[ותנא זה מביא,\u0006 למד \u0005אותה מכאן],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003את זו דרש ר' ישמעאל בר' יוסי,\u0004 נאמר: \u0003\"איש כי ימות ובן אין לו\u0004 והעברתם את נחלתו לבתו\u0003\"\u0004 (במדבר כז, ח), ומלשון \"והעברתם\" הוא למד: \u0003במקום\u0004 שיש \u0003בת אתה מעביר נחלה\u0004 ממי שיש לו לכאורה זכות ירושה מוקדמת, כלומר, \u0003מן האב,\u0004 ומכאן יש לדייק: \u0003ואי\u0004 (ואין) \u0003אתה מעביר נחלה מן האב במקום אחין,\u0004 שלא נאמר כן בקרובים אחרים כשהאב קרוב יותר מהם למת, כגון אחים.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ודרוש כתוב זה באותה דרך, אך באופן אחר: \u0003במקום\u0004 שיש \u0003בת אתה מעביר נחלה מן האחין,\u0004"],["\u0003ואי\u0004 (אין) \u0003אתה מעביר נחלה מן האב אפילו במקום בת,\u0004 ויקדם האב בירושה לבת! ומשיבים: \u0003אם כן, לא נכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 בלשון \u0003\"והעברתם\u0004 את נחלתו לבתו","\u0003\",\u0004 לפי שזה שהבת קודמת לאחים בירושה — אין זו העברה, שהרי פשוט הדבר שהבת קרובה לאביה יותר מאשר אחיו! אלא ודאי בא הכתוב להקדימה אף לאב. מצאנו איפוא שתי דרכי מדרש מהן למדנו שהאב קודם לאחים בירושה. ועתה דנים בהן, ושואלים: \u0003ולמאן דנפקא ליה\u0004 \u0005[ולמי שיוצא לו]\u0006 דין זה \u0003מ\u0004הכתוב \u0003\"והעברתם\", האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"שארו\"\u0004 שהוסבר שזהו האב, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו]?\u0006 כיצד הוא דורשו? ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך\u0006 הוא \u0005לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"שארו\"\u0004 — \u0003זו אשתו, מלמד שהבעל יורש את אשתו.\u0004","ושואלים מצד שני: \u0003ולמאן דנפקא ליה\u0004 \u0005[ולמי שיוצא לו]\u0006 דין זה שהאב קודם לאחים \u0003מ\u0004מה שכתוב \u0003\"שארו\", האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"והעברתם\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך\u0006 הוא \u0005אותו לכפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: בכולן,\u0004 בכל היורשים, \u0003נאמר בהן\u0004 לשון \u0003\"נתינה\"\u0004 (\"ונתתם\"), \u0003וכאן נאמרה בהן\u0004 (בבנות) לשון \u0003\"העברה\"\u0004 (\"והעברתם\"), לומר \u0003שאין לך שמעביר נחלה משבט לשבט אלא בת, הואיל ובנה ובעלה יורשין אותה\u0004 אם נישאה לבן שבט אחר. ומכאן למדנו שהבן יורש את אמו.","ושואלים על הלימוד מ\"שארו\": \u0003וממאי\u0004 \u0005[וממה,\u0006 מהיכן\u0005]\u0006 אתה יודע ש\u0003\"שארו\"\u0004 האמור לענין נחלה (במדבר כז, יא) \u0003זה האב? דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"שאר אביך הוא\"\u0004 (ויקרא יח, יב), \u0003אימא\u0004 \u0005[אמור]\u0006 באופן שונה: \u0003\"שארו\"\u0004 — \u0003זו האם, דכתיב\u0004 \u0005[שנאמר]\u0006 גם כן: \u0003\"שאר אמך הוא\"\u0004 (ויקרא יח, יג)!","\u0003אמר רבא, אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין נחלה: \u0003\"\u0004ונתתם את נחלתו לשארו הקרוב אליו \u0003ממשפחתו וירש אתה\"\u0004 (במדבר כז, יא), ובכך הדגיש הכתוב כי \"שארו\" הוא דווקא זה שהוא ממשפחתו. והרי \u0003משפחת אב\u0004 היא ה\u0003קרויה \"משפחה\", משפחת אם אינה קרויה \"משפחה\",\u0004 וראיה לדבר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"למשפחתם לבית אבתם\"\u0004 (במדבר א, ב).","ומקשים: \u0003ו\u0004כי \u0003משפחת אם אינה קרויה \"משפחה\"? והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויהי נער מבית לחם יהודה ממשפחת יהודה והוא לוי והוא גר שם\"\u0004 (שופטים יז, ז), ונברר: \u0003הא גופא קשיא\u0004 \u0005[זה עצמו קשה],\u0006 \u0003אמרת\u0004 מצד אחד \u0003\"והוא לוי\"\u0004 — \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מ\u0004שבט \u0003לוי אתי\u0004 \u0005[בא],\u0006 ואחר כך נאמר \u0003\"ממשפחת יהודה\"\u0004 — \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מ\u0004שבט \u0003יהודה אתי\u0004 \u0005[בא]!\u0006 \u0003אלא לאו דאבוה\u0004 \u0005[האם לא שאביו]\u0006 \u0003מ\u0004שבט \u0003לוי ואימיה\u0004 \u0005[ואמו]\u0006 \u0003מ\u0004שבט \u0003יהודה, וקאמר\u0004 \u0005[ואמר]\u0006 הכתוב עליו שהוא \u0003\"ממשפחת יהודה\",\u0004 משמע שגם משפחת האם קרויה משפחה!","\u0003אמר רבא בר רב חנן\u0004 בתירוץ: \u0003לא\u0004 זה ההסבר לתירוץ הקושי, אלא באופן זה: היה זה \u0003גברא דשמיה\u0004 \u0005[איש ששמו\u0006 הפרטי היה\u0005]\u0006 \u0003לוי,\u0004 אך אביו היה משבט יהודה. ומקשים על פירוש זה: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 האם \u0003היינו דקאמר\u0004 \u0005[זהו מה שאמר]\u0006 \u0003מיכה\u0004 כשלקח אותו לכהן לעבודה זרה: \u0003\"עתה ידעתי כי ייטיב ה' לי כי היה לי הלוי לכהן\"\u0004 (שופטים יז, יג)? שאם היה אותו נער לוי ממש, מובן הדבר שהיה זה עבורו סימן טוב שיש לוי המשמש לו ככהן, אבל אם אין זה אלא שמו, האם יש כלל יתרון בכך ששמו הפרטי של אותו נער היה לוי? השיב רבא בר רב חנן: \u0003אין\u0004 \u0005[כן],\u0006 גם בזה ראה מיכה סימן יפה, \u0003דאיתרמי ליה גברא דשמיה\u0004 \u0005[שהזדמן לו אדם ששמו]\u0006 \u0003לוי.\u0004","ותוהים עוד: \u0003וכי\u0004 יכול אתה לומר ש\u0003לוי\u0004 היה \u0003שמו? והלא יהונתן שמו, שנאמר: \"ויהונתן בן גרשם בן מנשה הוא ובניו היו כהנים לשבט הדני\"\u0004 (שופטים יח, ל)! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בר רב חנן: \u0003וליטעמיך\u0004 \u0005[ו\u0006הרי אף \u0005לטעמך,\u0006 לשיטתך\u0005],\u0006 שאתה למד שלא היה שמו לוי אלא שם שבטו הוא, ומסתמך על פסוק זה, יש לשאול: \u0003וכי\u0004 אותו נער \u0003בן מנשה הוא? והלא בן משה הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בני משה גרשום ואליעזר\"\u0004 (דברי הימים א' כג, טו)!","\u0003אלא,\u0004 כפי שדרשו חכמים, אף שבנו של משה היה, \u0003מתוך שעשה מעשה\u0004 כ\u0003מנשה\u0004 מלך יהודה, שעבד עבודה זרה, \u0003תלאו הכתוב במנשה\u0004 וקרא לו \"בן מנשה\". ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בפסוק ממנו אתה מוכיח שמשפחת האם קרויה משפחה (שהרי נאמר \"ממשפחת יהודה\") יש לפרש שאין בזה יחוס משפחתי ממש, אלא \u0003מתוך שעשה מעשה מנשה דאתי\u0004 \u0005[שבא]\u0006 \u0003מ\u0004שבט \u0003יהודה\u0004 — \u0003תלאו הכתוב ביהודה\u0004 וקרא לו \"ממשפחת יהודה\".","ומעירים: ממה שדרשו חכמים בענין מנשה, \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מכאן שתולין את הקלקלה במקולקל,\u0004 כלומר, כאשר יש דבר קלקלה, מקשרים אותו למי שידוע שמעשיו מקולקלים, אף שאין לו קשר מוכח אל הדבר. \u0003ר' יוסי בר חנינא אמר, מהכא\u0004 \u0005[מכאן]\u0006 למדים דבר זה, שנאמר באדוניה בן דוד: \u0003\"וגם הוא טוב תאר מאד ואתו ילדה אחרי אבשלום\"\u0004 (מלכים א א, ו), \u0003והלא אדניה\u0004 היה \u0003בן חגית ואבשלום\u0004 היה \u0003בן מעכה,\u0004 אם כן, מה פשר לשון \"ואותו ילדה אחרי אבשלום\", ממנה משמע שנולדו מאותה אם? \u0003אלא, מתוך שעשה\u0004 אדוניה \u0003מעשה אבשלום\u0004 ש\u0003מרד במלכות\u0004 — \u0003תלאו הכתוב באבשלום,\u0004 ועשאו כאחיו מכל צד, ואף מן האם. \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003מתוך שעשה\u0004 יהונתן זה \u0003מעשה מנשה\u0004 — \u0003תלאו הכתוב במנשה.\u0004","מתוך שהוזכר המעשה ביהונתן בן גרשום, מביאים לימוד אחר העולה מכאן. \u0003אמר\u0004 \u0003ר' אלעזר: לעולם ידבק אדם בטובים,\u0004 כלומר, ישא אשה ממשפחה טובה, שהדבר יביא טובה לילדים הנולדים להם, \u0003שהרי משה שנשא בת יתרו\u0004 שהיה כומר לעבודה זרה — \u0003יצא ממנו יהונתן\u0004 שאף הוא שימש לעבודה זרה, ואילו \u0003אהרן שנשא בת עמינדב\u0004 ממיוחסי שבט יהודה — \u0003יצא ממנו פנחס.\u0004","ותוהים: \u0003ו\u0004האם \u0003פנחס לאו\u0004 \u0005[לא]\u0006 \u0003מ\u0004משפחת \u0003יתרו אתי\u0004 \u0005[בא]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואלעזר בן אהרן לקח לו מבנות פוטיאל לו לאשה\"\u0004 (שמות ו, כה), \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003מיתרו\u0004 שכינוהו \"פוטיאל\" משום \u0003ש\u0004בשעתו \u0003פיטם עגלים לעבודה זרה?\u0004 ודוחים: \u0003לא,\u0004 אף ש\"פוטיאל\" כינוי הוא, הכוונה ב\"בן פוטיאל\" היא \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003מיוסף שפטפט\u0004 התווכח, נלחם ב\u0003יצרו\u0004 ונצחו.","ומקשים: \u0003והלא\u0004 יודעים אנו מן המדרש שהיו \u0003שבטים מבזים אותו\u0004 את פנחס, לאחר שהרג את זמרי (ראה במדבר פרק כה) \u0003ואומרים\u0004 עליו: \u0003ראיתם בן פוטי זה, בן\u0004 של מי \u0003שפיטם אבי אמו עגלים לעבודה זרה,\u0004 הוא \u0003יהרוג נשיא שבט מישראל?!\u0004"]]};
